// =====================================================================


window.TEXTOS_SEED["2reis"][1] = [
{s:"Ocozias consulta Belzebu"},
{v:1,t:"Depois da morte de Acab, Moab revoltou-se contra Israel.",n:"O Segundo Livro dos Reis continua o primeiro sem interrupção: vai do reinado de Ocozias à queda de Jerusalém e ao exílio da Babilônia, em 587 antes de Cristo."},
{v:2,t:"Ocozias caiu pela grade do seu quarto de cima, em Samaria, e ficou doente. Então enviou mensageiros, dizendo-lhes: Ide consultar Belzebu, deus de Acaron, para saber se sobreviverei a esta doença.",n:"Belzebu, à letra senhor das moscas: deformação zombeteira do nome Baal-Zebul, Baal príncipe, venerado em Acaron, cidade filisteia. Nos Evangelhos, Belzebu será o nome do príncipe dos demônios (Mateus 12,24)."},
{v:3,t:"Mas o anjo do Senhor disse a Elias, o tesbita: Levanta-te, sobe ao encontro dos mensageiros do rei de Samaria e dize-lhes: Acaso não há Deus em Israel, para irdes consultar Belzebu, deus de Acaron?"},
{v:4,t:"Por isso assim diz o Senhor: Não descerás da cama a que subiste, mas certamente morrerás. E Elias partiu."},
{v:5,t:"Os mensageiros voltaram a Ocozias, e ele lhes perguntou: Por que voltastes?",np:1},
{v:6,t:"Eles responderam: Um homem veio ao nosso encontro e nos disse: Ide, voltai ao rei que vos enviou e dizei-lhe: Assim diz o Senhor: Acaso não há Deus em Israel, para mandares consultar Belzebu, deus de Acaron? Por isso não descerás da cama a que subiste, mas certamente morrerás."},
{v:7,t:"Ele lhes perguntou: Qual era o aspecto do homem que veio ao vosso encontro e vos disse essas palavras?"},
{v:8,t:"Eles responderam: Era um homem vestido de pelos, com um cinto de couro à cintura. Ele disse: É Elias, o tesbita!",n:"O manto de pelos e o cinto de couro serão também o vestuário de João Batista, o novo Elias (Marcos 1,6; Mateus 11,14)."},
{s:"Elias e os chefes de cinquenta"},
{v:9,t:"O rei enviou-lhe um chefe de cinquenta com os seus cinquenta homens. Ele subiu até Elias, que estava sentado no alto do monte, e disse-lhe: Homem de Deus, o rei ordena: Desce!",np:1},
{v:10,t:"Elias respondeu ao chefe de cinquenta: Se sou homem de Deus, desça fogo do céu e te devore, a ti e aos teus cinquenta! E desceu fogo do céu e o devorou, a ele e aos seus cinquenta.",n:"Tiago e João quererão imitar Elias contra os samaritanos, e Jesus os repreenderá (Lucas 9,54-55)."},
{v:11,t:"O rei tornou a enviar-lhe outro chefe de cinquenta com os seus cinquenta homens, e este lhe disse: Homem de Deus, assim diz o rei: Desce depressa!"},
{v:12,t:"Elias respondeu-lhes: Se sou homem de Deus, desça fogo do céu e te devore, a ti e aos teus cinquenta! E desceu fogo de Deus do céu e o devorou, a ele e aos seus cinquenta."},
{v:13,t:"O rei enviou ainda um terceiro chefe de cinquenta com os seus cinquenta homens. Este subiu e, chegando, dobrou os joelhos diante de Elias e suplicou-lhe: Homem de Deus, que a minha vida e a vida destes cinquenta servos teus sejam preciosas aos teus olhos!",n:"O terceiro chefe não dá ordens ao profeta: suplica. A humildade o salva."},
{v:14,t:"Desceu fogo do céu e devorou os dois primeiros chefes de cinquenta com os seus homens; mas agora, peço-te, tem piedade da minha vida!"},
{v:15,t:"O anjo do Senhor disse a Elias: Desce com ele; não tenhas medo dele. Elias levantou-se e desceu com ele até o rei,"},
{v:16,t:"e disse-lhe: Assim diz o Senhor: Porque enviaste mensageiros para consultar Belzebu, deus de Acaron, como se não houvesse Deus em Israel para consultar a sua palavra, não descerás da cama a que subiste, mas certamente morrerás."},
{v:17,t:"E Ocozias morreu, segundo a palavra do Senhor que Elias tinha dito. Jorão, seu irmão, reinou em seu lugar, no segundo ano de Jorão, filho de Josafá, rei de Judá, porque Ocozias não tinha filho.",np:1,n:"Dois reis do mesmo nome, Jorão, reinam ao mesmo tempo em Israel e em Judá. As datas dos Reis nem sempre concordam entre si: talvez por causa de corregências, em que o filho reinava junto com o pai."},
{v:18,t:"O resto dos feitos de Ocozias, o que ele fez, não está escrito no livro dos Anais dos Reis de Israel?"}
];

window.TEXTOS_SEED["2reis"][2] = [
{s:"Elias arrebatado ao céu"},
{v:1,t:"Quando o Senhor quis arrebatar Elias ao céu num redemoinho, Elias e Eliseu partiram de Guilgal.",n:"Não se trata do Guilgal junto ao Jordão, mas de outro, na montanha, ao norte de Betel."},
{v:2,t:"Elias disse a Eliseu: Fica aqui, porque o Senhor me envia a Betel. Mas Eliseu respondeu: Pela vida do Senhor e pela tua vida, não te deixarei. E desceram a Betel.",n:"Três vezes Elias pede a Eliseu que fique, e três vezes Eliseu recusa: a fidelidade do discípulo é posta à prova."},
{v:3,t:"Os filhos dos profetas que estavam em Betel saíram ao encontro de Eliseu e lhe disseram: Sabes que hoje o Senhor vai tirar o teu senhor de sobre a tua cabeça? Ele respondeu: Eu também sei; calai-vos."},
{v:4,t:"Elias disse-lhe: Eliseu, fica aqui, porque o Senhor me envia a Jericó. Ele respondeu: Pela vida do Senhor e pela tua vida, não te deixarei. E chegaram a Jericó."},
{v:5,t:"Os filhos dos profetas que estavam em Jericó aproximaram-se de Eliseu e lhe disseram: Sabes que hoje o Senhor vai tirar o teu senhor de sobre a tua cabeça? Ele respondeu: Eu também sei; calai-vos."},
{v:6,t:"Elias disse-lhe: Fica aqui, porque o Senhor me envia ao Jordão. Ele respondeu: Pela vida do Senhor e pela tua vida, não te deixarei. E os dois continuaram juntos."},
{v:7,t:"Cinquenta homens dos filhos dos profetas os seguiram e pararam ao longe, defronte deles, enquanto os dois ficavam de pé à beira do Jordão.",np:1},
{v:8,t:"Então Elias tomou o seu manto, enrolou-o e bateu nas águas, que se dividiram de um lado e de outro; e os dois passaram a pé enxuto.",n:"Como Moisés no mar Vermelho e Josué no Jordão: Elias refaz ao contrário o caminho da entrada na terra, e sai dela para o lado do Nebo, onde morreu Moisés."},
{v:9,t:"Depois que passaram, Elias disse a Eliseu: Pede o que queres que eu faça por ti, antes que eu seja arrebatado do teu lado. Eliseu respondeu: Peço-te que eu receba duas partes do teu espírito.",n:"Duas partes: a porção dupla que cabia ao primogênito na herança (Deuteronômio 21,17). Eliseu pede para ser o herdeiro de Elias."},
{v:10,t:"Elias disse: Pedes uma coisa difícil. Mas, se me vires quando eu for arrebatado do teu lado, assim te acontecerá; se não me vires, não acontecerá."},
{v:11,t:"Enquanto iam andando e conversando, eis que um carro de fogo, com cavalos de fogo, os separou um do outro, e Elias subiu ao céu no redemoinho.",n:"Como Henoc (Gênesis 5,24), Elias não morre: é arrebatado. Daí a espera do seu retorno antes do Dia do Senhor (Malaquias 3,23), que os Evangelhos veem cumprida em João Batista; e Elias aparecerá ao lado de Moisés na transfiguração de Jesus."},
{v:12,t:"Eliseu via e gritava: Meu pai, meu pai! Carro de Israel e seu cavaleiro! E não o viu mais. Então tomou as suas vestes e as rasgou em duas partes.",n:"Carro de Israel e seu cavaleiro: Elias era a verdadeira força de Israel, mais que os carros de guerra. Os mesmos títulos serão dados a Eliseu na hora da sua morte (13,14)."},
{v:13,t:"Levantou o manto que tinha caído de Elias, voltou e parou à beira do Jordão."},
{v:14,t:"Com o manto que tinha caído de Elias bateu nas águas e disse: Onde está agora o Senhor, o Deus de Elias? Bateu nas águas, e elas se dividiram de um lado e de outro, e Eliseu passou."},
{v:15,t:"Os filhos dos profetas, que estavam em Jericó, defronte, vendo-o, disseram: O espírito de Elias repousa sobre Eliseu. Vieram ao seu encontro e prostraram-se diante dele com o rosto em terra,",np:1},
{v:16,t:"e lhe disseram: Há entre os teus servos cinquenta homens valentes; deixa-os ir procurar o teu senhor: talvez o Espírito do Senhor o tenha arrebatado e lançado em algum monte ou em algum vale. Ele disse: Não mandeis ninguém."},
{v:17,t:"Mas insistiram tanto com ele, até que, envergonhado, disse: Mandai. Mandaram cinquenta homens, que o procuraram durante três dias, mas não o encontraram,"},
{v:18,t:"e voltaram a Eliseu, que ficara em Jericó. Ele lhes disse: Não vos disse que não fôsseis?"},
{s:"Os primeiros milagres de Eliseu"},
{v:19,t:"Os homens da cidade disseram a Eliseu: A situação desta cidade é boa, como o meu senhor pode ver; mas as águas são más, e a terra faz abortar.",np:1},
{v:20,t:"Ele disse: Trazei-me um prato novo e ponde nele sal. Eles o trouxeram,"},
{v:21,t:"e ele foi à fonte das águas, lançou nela o sal e disse: Assim diz o Senhor: Eu saneei estas águas; já não haverá nelas morte nem aborto.",n:"A fonte de Jericó, abundante, ainda hoje é chamada fonte de Eliseu."},
{v:22,t:"E as águas ficaram saneadas até hoje, segundo a palavra que Eliseu tinha dito."},
{v:23,t:"De lá Eliseu subiu a Betel. Enquanto subia pelo caminho, uns rapazes saíram da cidade e zombavam dele, dizendo: Sobe, careca! Sobe, careca!",np:1,n:"Sobe: os rapazes zombam talvez do arrebatamento de Elias. Betel era o centro do culto do bezerro de ouro, hostil aos profetas do Senhor."},
{v:24,t:"Ele se voltou, olhou para eles e os amaldiçoou em nome do Senhor. Saíram do bosque duas ursas e despedaçaram quarenta e dois deles.",n:"A história, que choca o leitor moderno, quer mostrar que zombar do profeta é zombar de Deus. Pertence ao estilo das lendas populares sobre Eliseu, e não deve ser tomada como modelo: Jesus proibirá aos discípulos amaldiçoar os que os rejeitam."},
{v:25,t:"Dali foi para o monte Carmelo, e depois voltou para Samaria."}
];

window.TEXTOS_SEED["2reis"][3] = [
{s:"Jorão, rei de Israel"},
{v:1,t:"Jorão, filho de Acab, começou a reinar sobre Israel, em Samaria, no décimo oitavo ano de Josafá, rei de Judá, e reinou doze anos."},
{v:2,t:"Fez o que é mau aos olhos do Senhor, mas não como seu pai e sua mãe, pois retirou a estela de Baal que seu pai tinha feito."},
{v:3,t:"Mas apegou-se aos pecados de Jeroboão, filho de Nabat, que tinha feito Israel pecar, e não se afastou deles."},
{s:"A guerra contra Moab"},
{v:4,t:"Mesa, rei de Moab, era criador de ovelhas, e pagava ao rei de Israel um tributo de cem mil cordeiros e a lã de cem mil carneiros.",np:1,n:"Mesa deixou uma inscrição, a estela de Mesa, encontrada em 1868, em que narra a sua revolta contra o filho de Amri e atribui a vitória ao seu deus Camos."},
{v:5,t:"Mas, depois da morte de Acab, o rei de Moab revoltou-se contra o rei de Israel."},
{v:6,t:"Então o rei Jorão saiu de Samaria e passou em revista todo o Israel."},
{v:7,t:"Depois mandou dizer a Josafá, rei de Judá: O rei de Moab revoltou-se contra mim. Queres vir comigo combater contra Moab? Ele respondeu: Irei. Eu sou como tu, o meu povo como o teu povo, os meus cavalos como os teus cavalos."},
{v:8,t:"E perguntou: Por que caminho subiremos? Jorão respondeu: Pelo caminho do deserto de Edom.",n:"Para atacar Moab pelo sul, contornando o mar Morto, com o apoio de Edom, então vassalo de Judá."},
{v:9,t:"Partiram, pois, o rei de Israel, o rei de Judá e o rei de Edom. Depois de uma marcha de sete dias em volta, faltou água para o exército e para os animais que os seguiam."},
{v:10,t:"O rei de Israel disse: Ai de nós! O Senhor reuniu estes três reis para entregá-los nas mãos de Moab!"},
{v:11,t:"Mas Josafá perguntou: Não há aqui algum profeta do Senhor, para consultarmos o Senhor por meio dele? Um dos servos do rei de Israel respondeu: Está aqui Eliseu, filho de Safat, que derramava água nas mãos de Elias.",np:1,n:"Derramava água nas mãos de Elias: era o seu servo e discípulo."},
{v:12,t:"Josafá disse: A palavra do Senhor está com ele. E o rei de Israel, Josafá e o rei de Edom desceram até ele."},
{v:13,t:"Eliseu disse ao rei de Israel: Que tenho eu contigo? Vai aos profetas de teu pai e aos profetas de tua mãe. O rei de Israel lhe respondeu: Não! Foi o Senhor que reuniu estes três reis para entregá-los nas mãos de Moab."},
{v:14,t:"Eliseu disse: Pela vida do Senhor dos exércitos, a quem sirvo: se não fosse por respeito a Josafá, rei de Judá, eu nem olharia para ti nem te veria."},
{v:15,t:"Agora, pois, trazei-me um tocador de harpa. E, enquanto o tocador tocava, a mão do Senhor veio sobre Eliseu,",n:"A música dispunha o profeta ao êxtase, como nos grupos de profetas do tempo de Saul (1 Samuel 10,5)."},
{v:16,t:"e ele disse: Assim diz o Senhor: Cavai neste vale muitas covas."},
{v:17,t:"Porque assim diz o Senhor: Não vereis vento nem chuva, e este vale se encherá de água, e bebereis vós, os vossos rebanhos e os vossos animais."},
{v:18,t:"E isso ainda é pouco aos olhos do Senhor: ele entregará também Moab nas vossas mãos."},
{v:19,t:"Destruireis todas as cidades fortificadas e todas as cidades escolhidas; cortareis todas as árvores frutíferas, tapareis todas as fontes de água e cobrireis de pedras todos os campos férteis.",n:"Práticas de guerra que o Deuteronômio proibia, ao menos quanto às árvores frutíferas (Deuteronômio 20,19-20)."},
{v:20,t:"Na manhã seguinte, na hora em que se oferece o sacrifício, eis que vieram águas pelo caminho de Edom, e a terra ficou cheia de água.",n:"Uma tempestade nas montanhas de Edom encheu de repente o vale seco: fenômeno conhecido no deserto."},
{v:21,t:"Todos os moabitas, sabendo que os reis tinham subido para combatê-los, convocaram todos os que podiam cingir o cinturão, dos mais moços aos mais velhos, e postaram-se na fronteira.",np:1},
{v:22,t:"De manhã cedo, quando se levantaram e o sol brilhava sobre as águas, os moabitas viram defronte deles as águas vermelhas como sangue,"},
{v:23,t:"e disseram: É sangue! Os reis combateram entre si e se mataram uns aos outros. E agora, Moab, ao saque!"},
{v:24,t:"E foram ao acampamento de Israel. Mas os israelitas se levantaram e bateram os moabitas, que fugiram diante deles; e os perseguiram, batendo os moabitas."},
{v:25,t:"Destruíram as cidades; cada um atirou a sua pedra em todos os campos férteis, até enchê-los; taparam todas as fontes de água e cortaram todas as árvores frutíferas; só restaram as muralhas de Quir-Haréset, e os fundibulários a cercaram e a atacaram."},
{v:26,t:"Vendo que a batalha estava perdida, o rei de Moab tomou consigo setecentos homens armados de espada, para abrir caminho até o rei de Edom; mas não conseguiram."},
{v:27,t:"Então tomou o seu filho primogênito, que devia reinar em seu lugar, e o ofereceu em holocausto sobre a muralha. Houve grande indignação contra Israel, e eles se retiraram e voltaram para a sua terra.",n:"O sacrifício do filho do rei, ato extremo de súplica ao deus Camos, aterroriza os sitiantes. O texto não explica de onde vem a indignação: talvez o horror do próprio Israel, que se sente culpado de ter levado o inimigo a tal extremo."}
];

window.TEXTOS_SEED["2reis"][4] = [
{s:"O azeite da viúva"},
{v:1,t:"A mulher de um dos filhos dos profetas clamou a Eliseu: O teu servo, meu marido, morreu, e tu sabes que o teu servo temia o Senhor; e agora o credor veio para levar os meus dois filhos como escravos.",n:"A Lei permitia que o devedor insolvente pagasse com o trabalho dos filhos, mas mandava tratá-los como assalariados e libertá-los no ano jubilar (Levítico 25,39-41). Os milagres de Eliseu, contados como pequenas histórias populares, mostram Deus atento aos pobres."},
{v:2,t:"Eliseu lhe disse: Que queres que eu faça por ti? Dize-me: que tens em casa? Ela respondeu: A tua serva não tem nada em casa, senão uma botija de azeite."},
{v:3,t:"Ele disse: Vai, pede emprestadas a todos os teus vizinhos vasilhas vazias, e não poucas;"},
{v:4,t:"depois entra, fecha a porta atrás de ti e dos teus filhos, e derrama o azeite em todas essas vasilhas; e, à medida que forem ficando cheias, põe-nas de lado."},
{v:5,t:"Ela foi e fechou a porta atrás de si e dos filhos: eles lhe traziam as vasilhas, e ela derramava."},
{v:6,t:"Quando as vasilhas ficaram cheias, ela disse a um dos filhos: Traze-me mais uma vasilha. Ele respondeu: Não há mais nenhuma. E o azeite parou."},
{v:7,t:"Ela foi contá-lo ao homem de Deus, e ele disse: Vai, vende o azeite e paga a tua dívida; e tu e os teus filhos vivereis do resto."},
{s:"A sunamita e o seu filho"},
{v:8,t:"Um dia, Eliseu passava por Sunam. Havia ali uma mulher importante, que insistiu com ele para que comesse em sua casa. E, desde então, sempre que passava por ali, ele se hospedava em sua casa para comer.",np:1},
{v:9,t:"Ela disse ao marido: Tenho reparado que este homem que passa sempre por aqui é um santo homem de Deus."},
{v:10,t:"Façamos em cima, no terraço, um pequeno quarto de alvenaria, e ponhamos nele uma cama, uma mesa, uma cadeira e uma lâmpada; assim, quando ele vier à nossa casa, poderá ficar ali."},
{v:11,t:"Um dia, Eliseu chegou, retirou-se para o quarto de cima e descansou ali."},
{v:12,t:"Disse a Giezi, seu servo: Chama esta sunamita. Ele a chamou, e ela se apresentou diante dele."},
{v:13,t:"Eliseu disse a Giezi: Dize-lhe: Tu te deste a todo este trabalho por nossa causa; que posso fazer por ti? Precisas de alguma coisa? Queres que eu fale por ti ao rei ou ao chefe do exército? Ela respondeu: Eu vivo no meio da minha gente.",n:"Eu vivo no meio da minha gente: não preciso de proteção, tenho a minha família e a minha terra."},
{v:14,t:"Eliseu perguntou: Que se pode fazer por ela? Giezi respondeu: Ela não tem filho, e o marido é velho."},
{v:15,t:"Eliseu disse: Chama-a. Ele a chamou, e ela ficou de pé à porta."},
{v:16,t:"Eliseu disse: Por esta época, daqui a um ano, terás um filho nos braços. Ela respondeu: Não, meu senhor, homem de Deus, não enganes a tua serva!",n:"Como Sara, à qual o Senhor anunciou um filho no mesmo prazo (Gênesis 18,10-14)."},
{v:17,t:"A mulher concebeu e deu à luz um filho, na mesma época, um ano depois, como Eliseu lhe tinha dito."},
{v:18,t:"O menino cresceu. Um dia, foi ter com seu pai, junto dos ceifadores,",np:1},
{v:19,t:"e disse ao pai: Ai, a minha cabeça! Ai, a minha cabeça! O pai disse a um servo: Leva-o à mãe dele.",n:"Talvez uma insolação, no calor da colheita."},
{v:20,t:"O servo o tomou e o levou à mãe. Ela o teve no colo até o meio-dia, e ele morreu."},
{v:21,t:"Ela subiu, deitou-o na cama do homem de Deus, fechou a porta e saiu;"},
{v:22,t:"chamou o marido e lhe disse: Manda-me, por favor, um dos servos com uma jumenta; vou correndo ao homem de Deus e volto."},
{v:23,t:"Ele perguntou: Por que vais hoje ter com ele? Não é lua nova nem sábado. Ela respondeu: Fica em paz.",n:"Nos dias de festa, costumava-se visitar os profetas. A mulher não conta nada ao marido: vai, com fé silenciosa, ao homem de Deus."},
{v:24,t:"Mandou selar a jumenta e disse ao servo: Toca, e depressa; não me faças ir devagar, a não ser que eu te mande."},
{v:25,t:"Ela partiu e chegou junto do homem de Deus, no monte Carmelo. Quando o homem de Deus a viu ao longe, disse a Giezi, seu servo: Aí vem a sunamita."},
{v:26,t:"Corre ao seu encontro e pergunta-lhe: Tudo bem contigo? Tudo bem com o teu marido? Tudo bem com o menino? Ela respondeu: Tudo bem."},
{v:27,t:"Mas, quando chegou junto do homem de Deus, no monte, agarrou-se aos seus pés. Giezi aproximou-se para afastá-la, mas o homem de Deus disse: Deixa-a, porque a sua alma está amargurada, e o Senhor me escondeu isso e não me revelou."},
{v:28,t:"Ela disse: Acaso pedi um filho ao meu senhor? Não te disse: Não me enganes?"},
{v:29,t:"Eliseu disse a Giezi: Cinge os rins, toma o meu bastão na mão e vai. Se encontrares alguém, não o saúdes; e, se alguém te saudar, não lhe respondas. E porás o meu bastão sobre o rosto do menino.",n:"Não saudar ninguém pelo caminho: a missão não admite demora. Jesus dará a mesma ordem aos setenta e dois (Lucas 10,4)."},
{v:30,t:"Mas a mãe do menino disse: Pela vida do Senhor e pela tua vida, não te deixarei! Então ele se levantou e a seguiu."},
{v:31,t:"Giezi tinha ido adiante deles e posto o bastão sobre o rosto do menino; mas não houve voz nem sinal de vida. Voltou ao encontro de Eliseu e lhe disse: O menino não acordou.",n:"O bastão, sem a oração e a presença do profeta, não basta: não há magia."},
{v:32,t:"Eliseu entrou na casa, e eis que o menino estava morto, deitado na sua cama.",np:1},
{v:33,t:"Entrou, fechou a porta atrás de si e do menino, e orou ao Senhor."},
{v:34,t:"Depois subiu na cama e deitou-se sobre o menino, pondo a boca sobre a boca dele, os olhos sobre os olhos dele, as mãos sobre as mãos dele; estendeu-se sobre ele, e o corpo do menino se aqueceu.",n:"Como Elias com o filho da viúva de Sarepta (1 Reis 17,21): o profeta dá ao menino, por assim dizer, a sua própria vida."},
{v:35,t:"Depois desceu, andou pela casa de um lado para outro, tornou a subir e estendeu-se sobre ele; e o menino espirrou sete vezes e abriu os olhos."},
{v:36,t:"Eliseu chamou Giezi e disse: Chama esta sunamita. Ele a chamou, e ela entrou. Eliseu disse: Toma o teu filho."},
{v:37,t:"Ela entrou, lançou-se aos seus pés e prostrou-se por terra; depois tomou o filho e saiu."},
{s:"A panela envenenada"},
{v:38,t:"Eliseu voltou a Guilgal. Havia fome no país, e os filhos dos profetas estavam sentados diante dele. Ele disse ao seu servo: Põe a panela grande no fogo e cozinha um caldo para os filhos dos profetas.",np:1},
{v:39,t:"Um deles saiu ao campo para colher ervas; encontrou uma espécie de trepadeira silvestre e colheu dela coloquíntidas silvestres, até encher o manto. Voltou e cortou-as em pedaços na panela do caldo, sem saber o que eram.",n:"A coloquíntida silvestre é um purgante violento, que pode ser mortal."},
{v:40,t:"Serviram aos homens para comerem; mas, ao provarem o caldo, gritaram: A morte está na panela, homem de Deus! E não puderam comer."},
{v:41,t:"Eliseu disse: Trazei farinha. Lançou-a na panela e disse: Serve ao povo, para que coma. E já não havia nada de nocivo na panela."},
{s:"A multiplicação dos pães"},
{v:42,t:"Veio de Baal-Salisa um homem, trazendo ao homem de Deus pães das primícias: vinte pães de cevada e trigo novo no seu alforje. Eliseu disse: Dá ao povo, para que coma.",np:1,n:"As primícias eram oferecidas aos sacerdotes; aqui são trazidas ao profeta, num tempo em que o templo de Jerusalém estava longe do reino do Norte."},
{v:43,t:"Mas o seu servo respondeu: Como posso servir isto a cem homens? Ele repetiu: Dá ao povo, para que coma; porque assim diz o Senhor: Comerão, e ainda sobrará."},
{v:44,t:"Ele serviu-lhes; comeram, e ainda sobrou, segundo a palavra do Senhor.",n:"Os pães de cevada, a pergunta do servo e as sobras anunciam a multiplicação dos pães por Jesus, que os Evangelhos contam com as mesmas palavras (João 6,9-13)."}
];

window.TEXTOS_SEED["2reis"][5] = [
{s:"A cura de Naamã"},
{v:1,t:"Naamã, chefe do exército do rei da Síria, era um homem importante e estimado pelo seu senhor, porque foi por meio dele que o Senhor deu a vitória à Síria. Mas esse homem valente era leproso.",n:"O Senhor dá a vitória até aos inimigos de Israel: o Deus de Israel é o Senhor de todos os povos. Jesus lembrará que Naamã, um estrangeiro, foi purificado, enquanto muitos leprosos de Israel não o foram (Lucas 4,27)."},
{v:2,t:"Um bando de arameus tinha feito uma incursão na terra de Israel e levado cativa uma menina, que ficou a serviço da mulher de Naamã."},
{v:3,t:"Ela disse à sua senhora: Ah, se o meu senhor fosse ter com o profeta que está em Samaria! Ele o curaria da lepra.",n:"A salvação chega a Naamã pela boca de uma escrava estrangeira, que não guarda rancor aos seus senhores."},
{v:4,t:"Naamã foi contar ao seu senhor: Assim e assim falou a menina da terra de Israel."},
{v:5,t:"O rei da Síria lhe disse: Vai, e eu mandarei uma carta ao rei de Israel. Naamã partiu, levando consigo dez talentos de prata, seis mil siclos de ouro e dez mudas de roupa;"},
{v:6,t:"e entregou ao rei de Israel a carta, que dizia: Com esta carta, fica sabendo que te envio Naamã, meu servo, para que o cures da sua lepra."},
{v:7,t:"Quando o rei de Israel leu a carta, rasgou as vestes e disse: Acaso sou Deus, para dar a morte e a vida, para que este me mande curar um homem da sua lepra? Vede bem: ele procura pretexto contra mim!",n:"Só Deus faz morrer e faz viver (Deuteronômio 32,39). O rei não pensa no profeta."},
{v:8,t:"Quando Eliseu, o homem de Deus, soube que o rei de Israel tinha rasgado as vestes, mandou dizer ao rei: Por que rasgaste as vestes? Que ele venha a mim, e saberá que há um profeta em Israel."},
{v:9,t:"Naamã veio com os seus cavalos e os seus carros, e parou à porta da casa de Eliseu.",np:1},
{v:10,t:"Eliseu mandou-lhe dizer por um mensageiro: Vai, lava-te sete vezes no Jordão, e a tua carne ficará sã, e ficarás puro."},
{v:11,t:"Naamã irritou-se e foi-se embora, dizendo: Eu pensava que ele sairia ao meu encontro e, de pé, invocaria o nome do Senhor seu Deus, passaria a mão sobre o lugar doente e me curaria da lepra.",n:"Naamã esperava uma cerimônia à altura da sua importância; o profeta nem sequer sai de casa. A cura exige primeiro a humildade."},
{v:12,t:"Os rios de Damasco, o Abana e o Farfar, não são melhores que todas as águas de Israel? Não poderia eu lavar-me neles e ficar puro? E, voltando as costas, ia-se embora indignado."},
{v:13,t:"Mas os seus servos aproximaram-se e lhe disseram: Se o profeta te tivesse mandado fazer uma coisa difícil, não a farias? Quanto mais agora que ele te diz: Lava-te e ficarás puro!"},
{v:14,t:"Ele desceu e mergulhou sete vezes no Jordão, segundo a palavra do homem de Deus; e a sua carne tornou-se como a carne de uma criança, e ele ficou puro.",n:"A tradição cristã viu neste banho no Jordão uma figura do batismo."},
{v:15,t:"Voltou ao homem de Deus com toda a sua comitiva, apresentou-se diante dele e disse: Agora sei que não há Deus em toda a terra, senão em Israel! Aceita, pois, peço-te, um presente do teu servo.",np:1},
{v:16,t:"Mas Eliseu respondeu: Pela vida do Senhor, a quem sirvo, não aceitarei nada. Naamã insistiu, mas ele recusou.",n:"O dom de Deus é gratuito: o profeta não se deixa pagar. De graça recebestes, de graça dai (Mateus 10,8)."},
{v:17,t:"Naamã disse: Seja como queres. Mas permite que se dê ao teu servo a terra que duas mulas podem carregar; porque o teu servo não oferecerá mais holocausto nem sacrifício a outros deuses, senão ao Senhor.",n:"Segundo a mentalidade antiga, cada deus era adorado na sua terra: Naamã leva terra de Israel para poder adorar o Senhor em Damasco."},
{v:18,t:"Mas que o Senhor perdoe ao teu servo uma só coisa: quando o meu senhor entrar no templo de Remon para adorar, apoiado no meu braço, e eu me prostrar no templo de Remon enquanto ele ali se prostra, que o Senhor perdoe ao teu servo por isso.",n:"Remon, ou Hadad-Remon, era o deus da tempestade dos arameus. Naamã pede compreensão para um gesto exterior que as suas funções lhe impõem."},
{v:19,t:"Eliseu lhe disse: Vai em paz. E ele se afastou dele uma pequena distância.",n:"O profeta não exige do estrangeiro recém-convertido mais do que ele pode dar."},
{s:"O castigo de Giezi"},
{v:20,t:"Então Giezi, servo de Eliseu, homem de Deus, pensou: O meu senhor poupou este arameu, Naamã, não aceitando nada do que ele trouxe; pela vida do Senhor, vou correr atrás dele e aceitar alguma coisa.",np:1},
{v:21,t:"E Giezi foi atrás de Naamã. Quando Naamã o viu correndo atrás dele, desceu do carro ao seu encontro e perguntou: Está tudo bem?"},
{v:22,t:"Ele respondeu: Está tudo bem. O meu senhor me manda dizer: Acabam de chegar da montanha de Efraim dois jovens dos filhos dos profetas; dá-lhes, por favor, um talento de prata e duas mudas de roupa."},
{v:23,t:"Naamã disse: Aceita, antes, dois talentos. Insistiu com ele, amarrou dois talentos de prata em dois sacos, com duas mudas de roupa, e os deu a dois dos seus servos, que os levaram adiante de Giezi."},
{v:24,t:"Chegando à colina, Giezi tomou-os das mãos deles, guardou-os em casa e despediu os homens, que se foram."},
{v:25,t:"Depois foi apresentar-se diante do seu senhor. Eliseu lhe perguntou: De onde vens, Giezi? Ele respondeu: O teu servo não foi a lugar nenhum."},
{v:26,t:"Mas Eliseu lhe disse: Não estava presente o meu espírito quando o homem desceu do carro ao teu encontro? Acaso é tempo de aceitar prata e roupas, olivais e vinhas, ovelhas e bois, servos e servas?",n:"Giezi vende o dom de Deus que o profeta dera de graça: é o pecado que mais tarde se chamará simonia (Atos 8,18-20)."},
{v:27,t:"Por isso a lepra de Naamã se apegará a ti e à tua descendência para sempre. E Giezi saiu da sua presença leproso, branco como a neve."}
];

window.TEXTOS_SEED["2reis"][6] = [
{s:"O machado que flutuou"},
{v:1,t:"Os filhos dos profetas disseram a Eliseu: O lugar onde moramos junto de ti é pequeno demais para nós."},
{v:2,t:"Vamos até o Jordão; cada um tirará de lá uma viga, e construiremos ali um lugar para morarmos. Ele respondeu: Ide."},
{v:3,t:"Um deles disse: Vem também tu com os teus servos. Ele respondeu: Irei."},
{v:4,t:"E foi com eles. Chegando ao Jordão, começaram a cortar árvores."},
{v:5,t:"Enquanto um deles derrubava uma viga, o ferro do machado caiu na água; e ele gritou: Ai, meu senhor! Era emprestado!",n:"O ferro era raro e caro; o pobre profeta não teria como pagá-lo."},
{v:6,t:"O homem de Deus perguntou: Onde caiu? Ele lhe mostrou o lugar. Então Eliseu cortou um pedaço de pau, lançou-o ali e fez flutuar o ferro."},
{v:7,t:"E disse: Apanha-o. O homem estendeu a mão e o apanhou."},
{s:"Eliseu e os arameus cegos"},
{v:8,t:"O rei da Síria estava em guerra contra Israel. Deliberou com os seus servos, dizendo: Armaremos uma emboscada em tal e tal lugar.",np:1},
{v:9,t:"Mas o homem de Deus mandou dizer ao rei de Israel: Guarda-te de passar por tal lugar, porque os arameus estão ali em emboscada."},
{v:10,t:"O rei de Israel mandou gente ao lugar que o homem de Deus lhe indicara e sobre o qual o prevenira; e assim se guardou dali, não uma nem duas vezes."},
{v:11,t:"O coração do rei da Síria ficou perturbado com isso; convocou os seus servos e lhes disse: Não me direis quem dos nossos está do lado do rei de Israel?"},
{v:12,t:"Um dos seus servos respondeu: Ninguém, ó rei, meu senhor; mas Eliseu, o profeta que está em Israel, revela ao rei de Israel até as palavras que dizes no teu quarto de dormir."},
{v:13,t:"O rei disse: Ide ver onde ele está, para que eu mande prendê-lo. Informaram-lhe: Ele está em Dotã."},
{v:14,t:"O rei mandou para lá cavalos, carros e um forte destacamento, que chegaram de noite e cercaram a cidade."},
{v:15,t:"De manhã cedo, o servo do homem de Deus levantou-se e saiu, e viu que um exército cercava a cidade, com cavalos e carros. E disse a Eliseu: Ai, meu senhor, que faremos?"},
{v:16,t:"Ele respondeu: Não tenhas medo, porque os que estão conosco são mais numerosos que os que estão com eles."},
{v:17,t:"E Eliseu orou: Senhor, abre os olhos deste rapaz, para que ele veja. O Senhor abriu os olhos do rapaz, e ele viu: o monte estava cheio de cavalos e carros de fogo em volta de Eliseu.",n:"Os carros de fogo que levaram Elias protegem agora o seu discípulo. A fé vê o que os olhos não veem."},
{v:18,t:"Os arameus desceram contra ele, e Eliseu orou ao Senhor: Fere esta gente de cegueira! E o Senhor os feriu de cegueira, segundo a palavra de Eliseu."},
{v:19,t:"Eliseu lhes disse: Não é este o caminho, nem é esta a cidade. Segui-me, e eu vos levarei ao homem que procurais. E os levou a Samaria."},
{v:20,t:"Quando entraram em Samaria, Eliseu disse: Senhor, abre os olhos destes homens, para que vejam. O Senhor abriu-lhes os olhos, e eles viram que estavam no meio de Samaria."},
{v:21,t:"Quando o rei de Israel os viu, disse a Eliseu: Devo matá-los, meu pai?"},
{v:22,t:"Ele respondeu: Não os mates. Acaso matas os que fizeste prisioneiros com a tua espada e o teu arco? Serve-lhes pão e água, para que comam e bebam, e depois voltem para o seu senhor.",n:"Em vez da morte, um banquete: o profeta vence o inimigo com a misericórdia. Paulo dirá: se o teu inimigo tiver fome, dá-lhe de comer (Romanos 12,20)."},
{v:23,t:"Prepararam-lhes um grande banquete; comeram e beberam, e ele os despediu, e eles voltaram para o seu senhor. E os bandos arameus não voltaram mais à terra de Israel."},
{s:"A fome em Samaria"},
{v:24,t:"Depois disso, Ben-Adad, rei da Síria, reuniu todo o seu exército, subiu e sitiou Samaria.",np:1,n:"As histórias de Eliseu não seguem uma ordem cronológica: os arameus, que não deviam voltar, voltam."},
{v:25,t:"Houve grande fome em Samaria, e o cerco durou tanto que uma cabeça de jumento chegou a valer oitenta siclos de prata, e um quarto de cabo de esterco de pombas, cinco siclos de prata.",n:"A cabeça de jumento, animal impuro, era o que havia de pior. O esterco de pombas era talvez o nome popular de uma planta silvestre, ou de uma vagem comestível."},
{v:26,t:"Quando o rei de Israel passava pela muralha, uma mulher gritou-lhe: Socorro, ó rei, meu senhor!"},
{v:27,t:"Ele respondeu: Se o Senhor não te socorre, de onde poderei eu socorrer-te? Da eira ou do lagar? E o rei lhe perguntou: Que tens? Ela respondeu:"},
{v:28,t:"Esta mulher me disse: Dá o teu filho, para que o comamos hoje, e amanhã comeremos o meu."},
{v:29,t:"Cozinhamos o meu filho e o comemos. No dia seguinte eu lhe disse: Dá o teu filho, para que o comamos; mas ela escondeu o seu filho.",n:"O horror extremo da fome no cerco, anunciado pela maldição do Deuteronômio (Deuteronômio 28,53-57) e lamentado depois nas Lamentações (4,10)."},
{v:30,t:"Ao ouvir as palavras da mulher, o rei rasgou as vestes; e, como ele passava sobre a muralha, o povo viu que por baixo trazia um pano de saco sobre o corpo."},
{v:31,t:"E ele disse: Que Deus me faça isto e mais aquilo, se hoje a cabeça de Eliseu, filho de Safat, ficar sobre os seus ombros!",n:"O rei culpa o profeta pela desgraça, talvez porque Eliseu aconselhava a resistência."},
{v:32,t:"Eliseu estava sentado em sua casa, e os anciãos estavam sentados com ele. O rei enviou um homem adiante de si; mas, antes que o mensageiro chegasse, Eliseu disse aos anciãos: Vedes que esse filho de assassino mandou cortar-me a cabeça? Prestai atenção: quando o mensageiro chegar, fechai a porta e não o deixeis entrar. Não se ouve já atrás dele o ruído dos passos do seu senhor?",np:1,n:"Filho de assassino: filho de Acab, que matou Nabot e os profetas."},
{v:33,t:"Ele ainda estava falando com eles quando apareceu o rei, que descia até ele, e disse: Eis que esta desgraça vem do Senhor; que posso ainda esperar do Senhor?"}
];

window.TEXTOS_SEED["2reis"][7] = [
{s:"O fim do cerco"},
{v:1,t:"Eliseu disse: Ouvi a palavra do Senhor. Assim diz o Senhor: Amanhã, a esta hora, uma medida de flor de farinha valerá um siclo, e duas medidas de cevada valerão um siclo, à porta de Samaria."},
{v:2,t:"O oficial em cujo braço o rei se apoiava respondeu ao homem de Deus: Ainda que o Senhor abrisse janelas no céu, poderia acontecer o que dizes? Eliseu respondeu: Tu o verás com os teus olhos, mas não comerás disso.",n:"Janelas no céu: as comportas por onde caía a chuva, segundo a imagem antiga do mundo (Gênesis 7,11)."},
{s:"Os quatro leprosos"},
{v:3,t:"Havia quatro leprosos à entrada da porta, que disseram uns aos outros: Por que ficarmos aqui até morrer?",np:1,n:"Os leprosos viviam fora das muralhas (Levítico 13,46). A salvação da cidade será anunciada pelos excluídos."},
{v:4,t:"Se resolvermos entrar na cidade, morreremos lá, porque há fome na cidade; e, se ficarmos aqui, também morreremos. Vamos, pois, passar para o acampamento dos arameus: se nos pouparem a vida, viveremos; se nos matarem, morreremos."},
{v:5,t:"Levantaram-se ao anoitecer para ir ao acampamento dos arameus; e, quando chegaram à entrada do acampamento, não havia ali ninguém."},
{v:6,t:"Porque o Senhor tinha feito ouvir no acampamento dos arameus um ruído de carros, de cavalos e de um grande exército, e eles disseram uns aos outros: O rei de Israel contratou contra nós os reis dos heteus e os reis do Egito, para virem atacar-nos!"},
{v:7,t:"Levantaram-se e fugiram ao escurecer, abandonando as tendas, os cavalos e os jumentos, o acampamento tal como estava; e fugiram para salvar a vida."},
{v:8,t:"Os leprosos chegaram à entrada do acampamento, entraram numa tenda, comeram e beberam, e levaram de lá prata, ouro e roupas, e foram escondê-los. Voltaram, entraram em outra tenda, levaram também o que havia e foram escondê-lo."},
{v:9,t:"Depois disseram uns aos outros: Não estamos agindo bem. Hoje é dia de boas notícias, e nós ficamos calados! Se esperarmos até o amanhecer, seremos castigados. Vamos, pois, avisar o palácio do rei.",n:"A boa notícia não se guarda para si: é preciso anunciá-la. A palavra hebraica, besorá, é a que os gregos traduzirão por evangelho."},
{v:10,t:"Foram, chamaram os porteiros da cidade e lhes contaram: Fomos ao acampamento dos arameus, e não há ali ninguém, nem voz humana; só há cavalos e jumentos amarrados, e as tendas tal como estavam."},
{v:11,t:"Os porteiros gritaram a notícia, e ela foi anunciada dentro do palácio do rei."},
{v:12,t:"O rei levantou-se de noite e disse aos seus servos: Vou dizer-vos o que os arameus nos fizeram. Sabem que estamos passando fome; por isso saíram do acampamento e se esconderam no campo, pensando: Quando saírem da cidade, nós os prenderemos vivos e entraremos na cidade.",np:1},
{v:13,t:"Um dos seus servos respondeu: Tomemos cinco dos cavalos que restam na cidade — de qualquer modo, terão a sorte de toda a multidão de Israel que já pereceu —, e mandemos ver."},
{v:14,t:"Tomaram dois carros com cavalos, e o rei os mandou atrás do exército arameu, dizendo: Ide e vede."},
{v:15,t:"Eles os seguiram até o Jordão; e todo o caminho estava cheio de roupas e objetos que os arameus tinham jogado fora na sua fuga precipitada. Os mensageiros voltaram e contaram tudo ao rei."},
{v:16,t:"Então o povo saiu e saqueou o acampamento dos arameus; e uma medida de flor de farinha passou a valer um siclo, e duas medidas de cevada, um siclo, segundo a palavra do Senhor.",np:1},
{v:17,t:"O rei tinha posto de guarda à porta o oficial em cujo braço se apoiava; e o povo o pisoteou na porta, e ele morreu, como o homem de Deus tinha dito quando o rei descera até ele."},
{v:18,t:"Aconteceu segundo a palavra que o homem de Deus tinha dito ao rei: Amanhã, a esta hora, duas medidas de cevada valerão um siclo, e uma medida de flor de farinha, um siclo, à porta de Samaria;"},
{v:19,t:"quando o oficial respondeu ao homem de Deus: Ainda que o Senhor abrisse janelas no céu, poderia acontecer o que dizes?, e ele lhe disse: Tu o verás com os teus olhos, mas não comerás disso."},
{v:20,t:"Foi isso mesmo o que lhe aconteceu: o povo o pisoteou na porta, e ele morreu.",n:"A repetição insiste: a palavra do profeta se cumpre até o fim, para o bem e para o mal."}
];

window.TEXTOS_SEED["2reis"][8] = [
{s:"A sunamita recupera as suas terras"},
{v:1,t:"Eliseu tinha dito à mulher cujo filho ele fizera reviver: Levanta-te, vai com a tua família morar onde puderes, como estrangeira, porque o Senhor chamou a fome, e ela virá sobre a terra durante sete anos."},
{v:2,t:"A mulher levantou-se e fez segundo a palavra do homem de Deus: partiu com a sua família e morou sete anos como estrangeira na terra dos filisteus."},
{v:3,t:"Ao fim dos sete anos, a mulher voltou da terra dos filisteus e foi reclamar ao rei a sua casa e os seus campos.",n:"Na sua ausência, as terras tinham passado para outros, talvez para a coroa."},
{v:4,t:"O rei estava conversando com Giezi, o servo do homem de Deus, dizendo: Conta-me todas as grandes coisas que Eliseu fez.",n:"Giezi ainda está a serviço do profeta: o episódio é talvez anterior à sua lepra (5,27)."},
{v:5,t:"E, enquanto ele contava ao rei como Eliseu tinha feito reviver um morto, chegou a mulher cujo filho ele fizera reviver, reclamando ao rei a sua casa e os seus campos. E Giezi disse: Ó rei, meu senhor, esta é a mulher, e este é o seu filho, que Eliseu fez reviver!"},
{v:6,t:"O rei interrogou a mulher, e ela lhe contou tudo. Então o rei confiou o caso a um oficial, dizendo: Restitui-lhe tudo o que lhe pertence, com todos os rendimentos dos campos, desde o dia em que ela deixou a terra até hoje."},
{s:"Eliseu e Hazael"},
{v:7,t:"Eliseu foi a Damasco. Ben-Adad, rei da Síria, estava doente, e lhe informaram: O homem de Deus veio até aqui.",np:1},
{v:8,t:"O rei disse a Hazael: Toma contigo um presente, vai ao encontro do homem de Deus e consulta por meio dele o Senhor, perguntando: Sobreviverei a esta doença?"},
{v:9,t:"Hazael foi ao seu encontro, levando consigo um presente, tudo o que havia de melhor em Damasco, a carga de quarenta camelos. Chegando, apresentou-se diante dele e disse: Teu filho Ben-Adad, rei da Síria, mandou-me perguntar-te: Sobreviverei a esta doença?"},
{v:10,t:"Eliseu lhe disse: Vai e dize-lhe: Sararás. Mas o Senhor me mostrou que ele certamente morrerá.",n:"A doença não o matará; mas Hazael o matará. O hebraico pode também ler-se: Dize-lhe: Não viverás."},
{v:11,t:"E o homem de Deus ficou com o olhar fixo nele, perturbado, até que o rosto se lhe cobriu de rubor; e o homem de Deus chorou."},
{v:12,t:"Hazael perguntou: Por que o meu senhor chora? Ele respondeu: Porque sei o mal que farás aos filhos de Israel: incendiarás as suas cidades fortificadas, matarás à espada os seus jovens, esmagarás as suas crianças e rasgarás o ventre das suas mulheres grávidas.",n:"O profeta chora sobre o seu povo, como Jesus chorará sobre Jerusalém (Lucas 19,41-44)."},
{v:13,t:"Hazael disse: Que é o teu servo, este cão, para fazer uma coisa tão grande? Eliseu respondeu: O Senhor me mostrou que serás rei da Síria.",n:"Assim Eliseu cumpre a missão confiada a Elias no Horeb (1 Reis 19,15)."},
{v:14,t:"Hazael deixou Eliseu e voltou ao seu senhor, que lhe perguntou: Que te disse Eliseu? Ele respondeu: Disse-me que certamente sararás."},
{v:15,t:"No dia seguinte, tomou uma coberta, molhou-a na água e estendeu-a sobre o rosto do rei, e ele morreu. E Hazael reinou em seu lugar.",n:"As inscrições assírias chamam Hazael filho de ninguém, isto é, usurpador."},
{s:"Jorão, rei de Judá"},
{v:16,t:"No quinto ano de Jorão, filho de Acab, rei de Israel — sendo Josafá rei de Judá —, Jorão, filho de Josafá, começou a reinar sobre Judá.",np:1},
{v:17,t:"Tinha trinta e dois anos quando começou a reinar, e reinou oito anos em Jerusalém."},
{v:18,t:"Andou no caminho dos reis de Israel, como tinha feito a casa de Acab, porque tinha casado com uma filha de Acab; e fez o que é mau aos olhos do Senhor.",n:"A filha de Acab é Atalia (versículo 26): a aliança com a casa de Acab introduz em Judá o culto de Baal."},
{v:19,t:"Mas o Senhor não quis destruir Judá, por amor de Davi, seu servo, conforme lhe tinha prometido dar sempre uma lâmpada, a ele e aos seus filhos."},
{v:20,t:"No seu tempo, Edom revoltou-se contra o domínio de Judá e fez para si um rei."},
{v:21,t:"Jorão foi a Seira com todos os seus carros; levantou-se de noite e bateu os edomitas, que o tinham cercado, e os comandantes dos carros; mas o povo fugiu para as suas tendas."},
{v:22,t:"Assim Edom se separou do domínio de Judá, até hoje. Naquele tempo também Lebna se revoltou."},
{v:23,t:"O resto dos feitos de Jorão, tudo o que ele fez, não está escrito no livro dos Anais dos Reis de Judá?"},
{v:24,t:"Jorão adormeceu com seus pais e foi sepultado com eles na Cidade de Davi; e seu filho Ocozias reinou em seu lugar."},
{s:"Ocozias, rei de Judá"},
{v:25,t:"No décimo segundo ano de Jorão, filho de Acab, rei de Israel, Ocozias, filho de Jorão, rei de Judá, começou a reinar.",np:1},
{v:26,t:"Ocozias tinha vinte e dois anos quando começou a reinar, e reinou um ano em Jerusalém. Sua mãe chamava-se Atalia, neta de Amri, rei de Israel.",n:"À letra, filha de Amri: na linguagem da Bíblia, a descendente."},
{v:27,t:"Andou no caminho da casa de Acab e fez o que é mau aos olhos do Senhor, como a casa de Acab, porque era aparentado com a casa de Acab."},
{v:28,t:"Foi com Jorão, filho de Acab, combater contra Hazael, rei da Síria, em Ramot de Galaad; e os arameus feriram Jorão."},
{v:29,t:"O rei Jorão voltou a Jezrael para se tratar das feridas que os arameus lhe tinham feito em Ramá, quando combatia contra Hazael, rei da Síria. E Ocozias, filho de Jorão, rei de Judá, desceu a Jezrael para visitar Jorão, filho de Acab, que estava doente.",n:"Os dois reis, primos e aliados, estarão juntos em Jezrael quando chegar a revolta de Jeú."}
];

window.TEXTOS_SEED["2reis"][9] = [
{s:"A unção de Jeú"},
{v:1,t:"O profeta Eliseu chamou um dos filhos dos profetas e lhe disse: Cinge os rins, toma na mão este frasco de óleo e vai a Ramot de Galaad.",n:"Eliseu cumpre a segunda missão confiada a Elias no Horeb (1 Reis 19,16). A revolta de Jeú, sangrenta, é apresentada como a execução da sentença de Elias contra a casa de Acab."},
{v:2,t:"Quando chegares lá, procura Jeú, filho de Josafá, filho de Namsi; entra, faze-o levantar-se do meio dos seus companheiros e leva-o a um quarto retirado."},
{v:3,t:"Toma o frasco de óleo, derrama-o sobre a cabeça dele e dize: Assim diz o Senhor: Eu te ungi rei de Israel. Depois abre a porta e foge, sem te demorares."},
{v:4,t:"O jovem, o servo do profeta, partiu para Ramot de Galaad.",np:1},
{v:5,t:"Quando chegou, os chefes do exército estavam sentados, e ele disse: Tenho uma palavra para ti, chefe. Jeú perguntou: Para qual de nós? Ele respondeu: Para ti, chefe."},
{v:6,t:"Jeú levantou-se e entrou na casa; o jovem derramou o óleo sobre a cabeça dele e disse: Assim diz o Senhor, Deus de Israel: Eu te ungi rei sobre o povo do Senhor, sobre Israel."},
{v:7,t:"Ferirás a casa de Acab, teu senhor, e eu vingarei da mão de Jezabel o sangue dos meus servos, os profetas, e o sangue de todos os servos do Senhor."},
{v:8,t:"Toda a casa de Acab perecerá; exterminarei da casa de Acab todos os homens, jovens e adultos, em Israel."},
{v:9,t:"Farei da casa de Acab o que fiz da casa de Jeroboão, filho de Nabat, e da casa de Baasa, filho de Aías."},
{v:10,t:"E os cães comerão Jezabel no campo de Jezrael, e não haverá quem a sepulte. Depois abriu a porta e fugiu."},
{v:11,t:"Quando Jeú saiu para junto dos servos do seu senhor, eles lhe perguntaram: Está tudo bem? Que veio fazer contigo esse louco? Ele respondeu: Conheceis o homem e a sua conversa.",np:1,n:"Os oficiais tratam o profeta de louco: os profetas em transe pareciam loucos aos olhos dos soldados."},
{v:12,t:"Eles disseram: Mentira! Conta-nos! Ele disse: Assim e assim me falou: Assim diz o Senhor: Eu te ungi rei de Israel."},
{v:13,t:"Imediatamente cada um tomou o seu manto e o estendeu debaixo dos pés dele, sobre os degraus; tocaram a trombeta e disseram: Jeú é rei!",n:"Estender os mantos era gesto de homenagem ao rei. A multidão fará o mesmo diante de Jesus na entrada em Jerusalém (Mateus 21,8)."},
{s:"A morte de Jorão e de Ocozias"},
{v:14,t:"Assim Jeú, filho de Josafá, filho de Namsi, conspirou contra Jorão. Jorão, com todo o Israel, tinha defendido Ramot de Galaad contra Hazael, rei da Síria,",np:1},
{v:15,t:"e tinha voltado a Jezrael para se tratar das feridas que os arameus lhe tinham feito quando combatia contra Hazael, rei da Síria. E Jeú disse: Se estais de acordo, que ninguém saia da cidade para ir levar a notícia a Jezrael."},
{v:16,t:"Jeú subiu ao carro e partiu para Jezrael, onde Jorão estava de cama; e Ocozias, rei de Judá, tinha descido para visitar Jorão."},
{v:17,t:"A sentinela que estava na torre de Jezrael viu a tropa de Jeú que vinha e disse: Vejo uma tropa. Jorão disse: Toma um cavaleiro e manda-o ao encontro deles, para perguntar: Vindes em paz?"},
{v:18,t:"O cavaleiro foi ao seu encontro e disse: Assim diz o rei: Vindes em paz? Jeú respondeu: Que tens tu com a paz? Passa para trás de mim e segue-me. A sentinela informou: O mensageiro chegou até eles, mas não volta."},
{v:19,t:"O rei enviou outro cavaleiro, que chegou até eles e disse: Assim diz o rei: Vindes em paz? Jeú respondeu: Que tens tu com a paz? Passa para trás de mim e segue-me."},
{v:20,t:"A sentinela informou: Ele chegou até eles, mas não volta. E o modo de conduzir é o de Jeú, filho de Namsi, porque conduz como um louco."},
{v:21,t:"Jorão disse: Atrelai o carro! Atrelaram-lhe o carro, e Jorão, rei de Israel, e Ocozias, rei de Judá, saíram, cada um no seu carro, ao encontro de Jeú; e o encontraram no campo de Nabot, de Jezrael.",n:"No campo de Nabot: o lugar do crime de Acab torna-se o lugar do castigo da sua casa (1 Reis 21,19)."},
{v:22,t:"Quando Jorão viu Jeú, perguntou: Vens em paz, Jeú? Ele respondeu: Que paz, enquanto duram as prostituições de Jezabel, tua mãe, e as suas muitas feitiçarias?",n:"Prostituições: a linguagem dos profetas chama assim a idolatria, infidelidade ao Senhor, esposo de Israel."},
{v:23,t:"Jorão deu meia-volta e fugiu, gritando a Ocozias: Traição, Ocozias!"},
{v:24,t:"Mas Jeú retesou o arco e atingiu Jorão entre os ombros; a flecha atravessou-lhe o coração, e ele caiu no seu carro."},
{v:25,t:"Jeú disse a Badacer, seu escudeiro: Levanta-o e lança-o no campo de Nabot, de Jezrael. Lembra-te: quando eu e tu íamos lado a lado a cavalo atrás de Acab, seu pai, o Senhor pronunciou contra ele este oráculo:"},
{v:26,t:"Tão certo como vi ontem o sangue de Nabot e o sangue de seus filhos, diz o Senhor, eu te retribuirei neste mesmo campo, diz o Senhor. Levanta-o, pois, e lança-o no campo, segundo a palavra do Senhor."},
{v:27,t:"Vendo isso, Ocozias, rei de Judá, fugiu pelo caminho de Bet-Gã. Jeú o perseguiu e disse: Feri também a este! E o feriram no seu carro, na subida de Gaver, junto a Jeblaam. Ele fugiu para Meguido e ali morreu.",np:1},
{v:28,t:"Os seus servos o levaram no carro para Jerusalém e o sepultaram no seu túmulo, junto de seus pais, na Cidade de Davi."},
{v:29,t:"Ocozias tinha começado a reinar sobre Judá no décimo primeiro ano de Jorão, filho de Acab."},
{s:"A morte de Jezabel"},
{v:30,t:"Jeú chegou a Jezrael. Quando Jezabel soube disso, pintou os olhos com antimônio, enfeitou a cabeça e pôs-se a olhar pela janela.",np:1,n:"Jezabel enfrenta a morte como rainha, com todas as suas insígnias."},
{v:31,t:"Quando Jeú entrava pela porta, ela disse: Vens em paz, Zambri, assassino do teu senhor?",n:"Zambri matou o rei Ela e reinou só sete dias (1 Reis 16,9-18): Jezabel anuncia a Jeú o mesmo fim."},
{v:32,t:"Jeú levantou os olhos para a janela e disse: Quem está do meu lado? Quem? E dois ou três eunucos se debruçaram para ele."},
{v:33,t:"Ele disse: Atirai-a embaixo! Eles a atiraram, e o seu sangue salpicou a parede e os cavalos, que a pisotearam."},
{v:34,t:"Jeú entrou, comeu e bebeu; depois disse: Ide ver aquela maldita e sepultai-a, porque é filha de rei."},
{v:35,t:"Foram sepultá-la, mas só encontraram o crânio, os pés e as palmas das mãos."},
{v:36,t:"Voltaram e o contaram a Jeú, e ele disse: É a palavra que o Senhor disse por meio do seu servo Elias, o tesbita: No campo de Jezrael os cães comerão a carne de Jezabel;",n:"Cumpre-se a palavra de Elias (1 Reis 21,23)."},
{v:37,t:"e o cadáver de Jezabel será como esterco sobre a face do campo, no campo de Jezrael, de modo que não se poderá dizer: Esta é Jezabel."}
];

window.TEXTOS_SEED["2reis"][10] = [
{s:"O extermínio da casa de Acab"},
{v:1,t:"Acab tinha setenta descendentes em Samaria. Jeú escreveu cartas e enviou-as a Samaria, aos notáveis da cidade, aos anciãos e aos tutores dos filhos de Acab, dizendo:"},
{v:2,t:"Logo que receberdes estas cartas, vós, que tendes convosco os filhos do vosso senhor, os carros e os cavalos, uma cidade fortificada e armas,"},
{v:3,t:"escolhei o melhor e o mais digno dos filhos do vosso senhor, ponde-o no trono de seu pai e combatei pela casa do vosso senhor."},
{v:4,t:"Eles ficaram muito aterrorizados e disseram: Dois reis não puderam resistir-lhe; como poderemos nós resistir?"},
{v:5,t:"Então o mordomo do palácio, o governador da cidade, os anciãos e os tutores mandaram dizer a Jeú: Somos teus servos; faremos tudo o que ordenares; não proclamaremos rei a ninguém; faze o que te parecer bem."},
{v:6,t:"Jeú escreveu-lhes uma segunda carta, dizendo: Se estais do meu lado e quereis obedecer-me, tomai as cabeças dos filhos do vosso senhor e vinde ter comigo amanhã, a esta hora, em Jezrael. Os setenta filhos do rei estavam com os notáveis da cidade, que os criavam.",n:"As cabeças dos filhos do vosso senhor: a expressão é ambígua de propósito, podendo significar os chefes. Jeú deixa que os notáveis de Samaria tomem a iniciativa do massacre e a responsabilidade dele."},
{v:7,t:"Quando a carta chegou, eles tomaram os filhos do rei e mataram os setenta; puseram as cabeças em cestos e as mandaram a Jeú, em Jezrael."},
{v:8,t:"O mensageiro veio e lhe anunciou: Trouxeram as cabeças dos filhos do rei. Ele respondeu: Ponde-as em dois montes à entrada da porta, até amanhã."},
{v:9,t:"De manhã, ele saiu e, de pé, disse a todo o povo: Vós sois inocentes. Fui eu que conspirei contra o meu senhor e o matei; mas quem matou todos estes?",np:1},
{v:10,t:"Sabei, pois, que não cairá por terra nenhuma das palavras que o Senhor pronunciou contra a casa de Acab: o Senhor cumpriu o que tinha dito por meio do seu servo Elias."},
{v:11,t:"E Jeú matou todos os que restavam da casa de Acab em Jezrael, todos os seus notáveis, os seus amigos e os seus sacerdotes, até não deixar nenhum sobrevivente.",n:"O profeta Oseias condenará mais tarde este banho de sangue: castigarei a casa de Jeú pelo sangue de Jezrael (Oseias 1,4). O zelo de Jeú ultrapassou a missão recebida."},
{v:12,t:"Depois partiu para Samaria. No caminho, quando estava em Bet-Equed dos Pastores,",np:1},
{v:13,t:"encontrou os irmãos de Ocozias, rei de Judá, e perguntou: Quem sois vós? Eles responderam: Somos os irmãos de Ocozias e descemos para saudar os filhos do rei e os filhos da rainha-mãe.",n:"A rainha-mãe era Jezabel. Os príncipes de Judá ainda não sabiam de nada."},
{v:14,t:"Ele disse: Prendei-os vivos! Prenderam-nos vivos e os degolaram junto à cisterna de Bet-Equed: quarenta e dois homens. Não deixou nenhum deles."},
{v:15,t:"Partindo dali, encontrou Jonadab, filho de Recab, que vinha ao seu encontro; saudou-o e lhe disse: O teu coração é leal para comigo, como o meu é para contigo? Jonadab respondeu: É. Se é, dá-me a tua mão. Ele lhe deu a mão, e Jeú o fez subir para junto de si, no carro,",np:1,n:"Jonadab, filho de Recab, era o fundador dos recabitas, grupo fiel ao Senhor que recusava a vida sedentária, o vinho e as casas, por fidelidade ao tempo do deserto (Jeremias 35)."},
{v:16,t:"e disse: Vem comigo e verás o meu zelo pelo Senhor. E, tendo-o feito subir ao seu carro,"},
{v:17,t:"levou-o a Samaria. E matou em Samaria todos os que restavam de Acab, até exterminá-los, segundo a palavra que o Senhor tinha dito a Elias."},
{s:"O massacre dos adoradores de Baal"},
{v:18,t:"Depois Jeú reuniu todo o povo e lhes disse: Acab serviu a Baal um pouco; Jeú o servirá muito mais.",np:1},
{v:19,t:"Agora, pois, convocai-me todos os profetas de Baal, todos os seus fiéis e todos os seus sacerdotes; que não falte ninguém, porque vou oferecer um grande sacrifício a Baal; quem faltar não viverá. Mas Jeú agia com astúcia, para exterminar os adoradores de Baal."},
{v:20,t:"Jeú disse: Proclamai uma assembleia solene em honra de Baal. E a proclamaram."},
{v:21,t:"Jeú mandou mensageiros por todo o Israel, e vieram todos os fiéis de Baal: não houve um só que não viesse. Entraram no templo de Baal, e o templo de Baal ficou cheio de ponta a ponta."},
{v:22,t:"Jeú disse ao encarregado do vestuário: Tira as vestes para todos os fiéis de Baal. E ele as tirou para eles."},
{v:23,t:"Então Jeú entrou no templo de Baal com Jonadab, filho de Recab, e disse aos fiéis de Baal: Procurai bem e vede se não há aqui convosco algum servo do Senhor, mas só fiéis de Baal."},
{v:24,t:"E entraram para oferecer sacrifícios e holocaustos. Mas Jeú tinha posto do lado de fora oitenta homens, dizendo-lhes: Quem deixar escapar um só dos homens que eu entregar nas vossas mãos pagará com a sua vida pela vida dele."},
{v:25,t:"Quando acabaram de oferecer o holocausto, Jeú disse aos guardas e aos oficiais: Entrai e matai-os; que ninguém escape! Os guardas e os oficiais os passaram ao fio da espada e os lançaram fora; e chegaram até o santuário do templo de Baal."},
{v:26,t:"Tiraram a estela de Baal e a queimaram,"},
{v:27,t:"e a despedaçaram. Demoliram também o templo de Baal e fizeram dele uma latrina, que existe até hoje."},
{s:"O reinado de Jeú"},
{v:28,t:"Assim Jeú exterminou Baal de Israel.",np:1},
{v:29,t:"Mas não se afastou dos pecados de Jeroboão, filho de Nabat, que fizera Israel pecar: não abandonou os bezerros de ouro que estavam em Betel e em Dã.",n:"Jeú elimina o culto de Baal, religião estrangeira, mas conserva o culto de Jeroboão, religião nacional do reino do Norte."},
{v:30,t:"O Senhor disse a Jeú: Porque fizeste bem o que é reto aos meus olhos, e fizeste contra a casa de Acab tudo o que eu tinha no coração, os teus filhos se sentarão no trono de Israel até a quarta geração.",n:"A dinastia de Jeú será a mais longa do reino do Norte: quase um século, até Zacarias (15,12)."},
{v:31,t:"Mas Jeú não se cuidou de andar de todo o coração na lei do Senhor, Deus de Israel, e não se afastou dos pecados de Jeroboão, que fizera Israel pecar."},
{v:32,t:"Naqueles dias, o Senhor começou a amputar o território de Israel; e Hazael os feriu em todas as fronteiras de Israel,",np:1},
{v:33,t:"desde o Jordão para o oriente, toda a terra de Galaad, de Gad, de Rúben e de Manassés, desde Aroer, que está junto à torrente do Arnon, Galaad e Basã.",n:"Toda a Transjordânia israelita cai nas mãos de Damasco. Um obelisco assírio mostra Jeú prostrado diante do rei Salmanasar III, pagando tributo."},
{v:34,t:"O resto dos feitos de Jeú, tudo o que ele fez e a sua valentia, não está escrito no livro dos Anais dos Reis de Israel?"},
{v:35,t:"Jeú adormeceu com seus pais, e o sepultaram em Samaria; e seu filho Joacaz reinou em seu lugar."},
{v:36,t:"Jeú reinou sobre Israel, em Samaria, vinte e oito anos."}
];

window.TEXTOS_SEED["2reis"][11] = [
{s:"Atalia e o menino Joás"},
{v:1,t:"Quando Atalia, mãe de Ocozias, viu que o seu filho tinha morrido, levantou-se e exterminou toda a descendência real.",n:"Atalia, filha de Acab e de Jezabel, única mulher a reinar em Jerusalém, quase extingue a dinastia de Davi. A promessa de Natã fica suspensa na vida de um menino."},
{v:2,t:"Mas Josaba, filha do rei Jorão, irmã de Ocozias, tomou Joás, filho de Ocozias, e o tirou às escondidas do meio dos filhos do rei que estavam sendo mortos, e o pôs com a sua ama no quarto das camas; e assim o esconderam de Atalia, e ele não foi morto.",n:"Segundo as Crônicas, Josaba era mulher do sacerdote Joiada (2 Crônicas 22,11)."},
{v:3,t:"Ele ficou escondido com ela na casa do Senhor durante seis anos, enquanto Atalia reinava sobre o país."},
{v:4,t:"No sétimo ano, Joiada mandou chamar os chefes de cem dos cários e da guarda, e os fez entrar consigo na casa do Senhor. Fez com eles uma aliança e, depois de os fazer jurar na casa do Senhor, mostrou-lhes o filho do rei.",np:1,n:"Os cários eram mercenários estrangeiros, originários da Ásia Menor, a serviço da guarda real, como antes os cereteus e feleteus de Davi."},
{v:5,t:"E deu-lhes esta ordem: Eis o que haveis de fazer: um terço de vós, os que entram de serviço no sábado, montará guarda no palácio do rei;"},
{v:6,t:"outro terço estará na porta de Sur, e outro terço na porta que fica atrás do quartel da guarda; e montareis guarda à casa, por turnos."},
{v:7,t:"Os dois grupos de vós que saem de serviço no sábado montarão guarda na casa do Senhor, junto do rei."},
{v:8,t:"Cercareis o rei, cada um com as armas na mão; e quem tentar entrar no recinto do templo será morto. Acompanhareis o rei aonde quer que ele vá."},
{v:9,t:"Os chefes de cem fizeram tudo o que o sacerdote Joiada lhes tinha ordenado. Cada um tomou os seus homens, os que entravam de serviço no sábado e os que saíam de serviço no sábado, e vieram ao sacerdote Joiada.",n:"Na troca da guarda do sábado, as duas turmas estavam presentes ao mesmo tempo: Joiada dispõe assim do dobro dos homens sem despertar suspeitas."},
{v:10,t:"O sacerdote deu aos chefes de cem as lanças e os escudos do rei Davi, que estavam na casa do Senhor."},
{v:11,t:"Os guardas postaram-se, cada um com as armas na mão, desde o lado direito do templo até o lado esquerdo, entre o altar e o templo, em volta do rei."},
{v:12,t:"Então Joiada fez sair o filho do rei, pôs-lhe o diadema e as insígnias; e o proclamaram rei e o ungiram. E bateram palmas, gritando: Viva o rei!",n:"As insígnias: à letra, o testemunho, talvez um documento com as cláusulas da aliança real, ou as palavras da Lei (Deuteronômio 17,18-19)."},
{s:"A morte de Atalia"},
{v:13,t:"Atalia ouviu o clamor do povo e foi ter com a multidão, na casa do Senhor.",np:1},
{v:14,t:"Viu o rei de pé no estrado, segundo o costume, e os chefes e as trombetas junto do rei, e todo o povo da terra em festa, tocando as trombetas. Então Atalia rasgou as vestes e gritou: Traição! Traição!"},
{v:15,t:"Mas o sacerdote Joiada deu esta ordem aos chefes de cem que comandavam o exército: Levai-a para fora do recinto; e quem a seguir, matai-o à espada. Porque o sacerdote tinha dito: Que ela não seja morta na casa do Senhor."},
{v:16,t:"Agarraram-na e a levaram pelo caminho da entrada dos Cavalos até o palácio, e ali ela foi morta."},
{v:17,t:"Joiada fez entre o Senhor, o rei e o povo uma aliança, para que fossem o povo do Senhor; e também entre o rei e o povo.",np:1,n:"A dinastia de Davi é restaurada com uma renovação da aliança: o rei e o povo pertencem ao Senhor."},
{v:18,t:"Todo o povo da terra foi ao templo de Baal e o demoliu; despedaçaram completamente os seus altares e as suas imagens, e mataram Matã, sacerdote de Baal, diante dos altares. O sacerdote pôs guardas na casa do Senhor;",n:"O templo de Baal em Jerusalém tinha sido construído talvez por Atalia, à imagem do de Samaria."},
{v:19,t:"depois tomou os chefes de cem, os cários, os guardas e todo o povo da terra, e fizeram descer o rei da casa do Senhor; entraram no palácio pelo caminho da porta dos Guardas, e ele se sentou no trono dos reis."},
{v:20,t:"Todo o povo da terra se alegrou, e a cidade ficou tranquila. Atalia tinha sido morta à espada no palácio do rei."}
];

window.TEXTOS_SEED["2reis"][12] = [
{s:"Joás, rei de Judá"},
{v:1,t:"Joás tinha sete anos quando começou a reinar."},
{v:2,t:"Joás começou a reinar no sétimo ano de Jeú, e reinou quarenta anos em Jerusalém. Sua mãe chamava-se Sébia, de Bersabeia."},
{v:3,t:"Joás fez o que é reto aos olhos do Senhor durante todo o tempo em que o sacerdote Joiada o instruiu.",n:"Durante todo o tempo: depois da morte de Joiada, segundo as Crônicas, Joás abandonou o Senhor e mandou apedrejar Zacarias, filho do sacerdote (2 Crônicas 24,17-22), o mártir que Jesus lembrará (Mateus 23,35)."},
{v:4,t:"Mas os lugares altos não foram suprimidos; o povo continuava a oferecer sacrifícios e a queimar incenso nos lugares altos."},
{s:"A restauração do templo"},
{v:5,t:"Joás disse aos sacerdotes: Todo o dinheiro consagrado que se trouxer à casa do Senhor, o dinheiro com que cada um paga o resgate da sua pessoa, e todo o dinheiro que alguém trouxer espontaneamente à casa do Senhor,",np:1,n:"O templo, construído havia mais de um século, precisava de reparos; e o saque de Atalia o tinha danificado."},
{v:6,t:"os sacerdotes o recebam, cada um dos seus conhecidos, e reparem os estragos da casa, onde quer que se encontrem estragos."},
{v:7,t:"Mas no vigésimo terceiro ano do rei Joás os sacerdotes ainda não tinham reparado os estragos do templo."},
{v:8,t:"Então o rei Joás chamou o sumo sacerdote Joiada e os sacerdotes e lhes disse: Por que não reparais os estragos do templo? De agora em diante, não recebereis mais o dinheiro dos vossos conhecidos, mas o entregareis para a reparação do templo."},
{v:9,t:"Os sacerdotes concordaram em não receber mais dinheiro do povo e em não se encarregarem mais dos reparos do templo."},
{v:10,t:"O sumo sacerdote Joiada tomou um cofre, fez um buraco na tampa e o pôs ao lado do altar, à direita de quem entra na casa do Senhor; e os sacerdotes que guardavam a entrada punham nele todo o dinheiro que se trazia à casa do Senhor.",n:"O cofre do templo, que Jesus observará quando a viúva pobre depositar nele as suas duas moedas (Marcos 12,41-44)."},
{v:11,t:"Quando viam que havia muito dinheiro no cofre, subiam o secretário do rei e o sumo sacerdote, recolhiam e contavam o dinheiro que se encontrava na casa do Senhor,"},
{v:12,t:"e o entregavam, contado e pesado, aos encarregados das obras da casa do Senhor; e estes o gastavam com os carpinteiros e os construtores que trabalhavam na casa do Senhor,"},
{v:13,t:"com os pedreiros e os cortadores de pedra, e na compra de madeira e de pedras talhadas, para reparar os estragos da casa do Senhor, e em tudo o que era preciso gastar para consertar a casa."},
{v:14,t:"Mas, com o dinheiro trazido à casa do Senhor, não se faziam para a casa do Senhor bacias de prata, facas, taças, trombetas, nem objeto algum de ouro ou de prata;"},
{v:15,t:"porque era dado aos operários, para repararem a casa do Senhor."},
{v:16,t:"E não se pediam contas aos homens a quem se entregava o dinheiro para pagar aos operários, porque agiam com honestidade."},
{v:17,t:"O dinheiro dos sacrifícios de reparação e dos sacrifícios pelo pecado não se trazia para a casa do Senhor: pertencia aos sacerdotes."},
{s:"O fim de Joás"},
{v:18,t:"Naquele tempo, Hazael, rei da Síria, subiu, atacou Gat e a tomou; depois resolveu subir contra Jerusalém.",np:1},
{v:19,t:"Então Joás, rei de Judá, tomou todas as coisas consagradas por Josafá, Jorão e Ocozias, seus pais, reis de Judá, e as que ele mesmo tinha consagrado, e todo o ouro que se encontrava nos tesouros da casa do Senhor e do palácio real, e as enviou a Hazael, rei da Síria; e ele se retirou de Jerusalém."},
{v:20,t:"O resto dos feitos de Joás, tudo o que ele fez, não está escrito no livro dos Anais dos Reis de Judá?"},
{v:21,t:"Os seus servos levantaram-se, fizeram uma conspiração e mataram Joás em Bet-Milo, na descida de Sila."},
{v:22,t:"Foram Jozacar, filho de Semaat, e Jozabad, filho de Somer, seus servos, que o feriram, e ele morreu. Sepultaram-no com seus pais na Cidade de Davi; e seu filho Amasias reinou em seu lugar."}
];

window.TEXTOS_SEED["2reis"][13] = [
{s:"Joacaz, rei de Israel"},
{v:1,t:"No vigésimo terceiro ano de Joás, filho de Ocozias, rei de Judá, Joacaz, filho de Jeú, começou a reinar sobre Israel, em Samaria, e reinou dezessete anos."},
{v:2,t:"Fez o que é mau aos olhos do Senhor e seguiu o pecado de Jeroboão, filho de Nabat, que fizera Israel pecar; não se afastou dele."},
{v:3,t:"A ira do Senhor inflamou-se contra Israel, e ele os entregou nas mãos de Hazael, rei da Síria, e nas mãos de Ben-Adad, filho de Hazael, durante todo esse tempo."},
{v:4,t:"Mas Joacaz implorou o Senhor, e o Senhor o ouviu, porque viu a opressão de Israel, oprimido pelo rei da Síria.",n:"O esquema do livro dos Juízes reaparece: pecado, opressão, súplica, libertação."},
{v:5,t:"O Senhor deu a Israel um salvador, e eles escaparam das mãos dos arameus; e os filhos de Israel puderam morar nas suas tendas como antes.",n:"O salvador não é nomeado: talvez o rei da Assíria, que atacou Damasco e aliviou a pressão sobre Israel; ou os reis Joás e Jeroboão II, que reconquistarão o território."},
{v:6,t:"Mas não se afastaram dos pecados da casa de Jeroboão, que fizera Israel pecar: continuaram neles; e também o poste sagrado ficou de pé em Samaria."},
{v:7,t:"Não restaram a Joacaz mais do que cinquenta cavaleiros, dez carros e dez mil soldados de infantaria, porque o rei da Síria os tinha exterminado e reduzido a pó, como o pó que se pisa na eira."},
{v:8,t:"O resto dos feitos de Joacaz, tudo o que ele fez e a sua valentia, não está escrito no livro dos Anais dos Reis de Israel?"},
{v:9,t:"Joacaz adormeceu com seus pais, e o sepultaram em Samaria; e seu filho Joás reinou em seu lugar."},
{s:"Joás, rei de Israel"},
{v:10,t:"No trigésimo sétimo ano de Joás, rei de Judá, Joás, filho de Joacaz, começou a reinar sobre Israel, em Samaria, e reinou dezesseis anos.",np:1},
{v:11,t:"Fez o que é mau aos olhos do Senhor; não se afastou de nenhum dos pecados de Jeroboão, filho de Nabat, que fizera Israel pecar: continuou neles."},
{v:12,t:"O resto dos feitos de Joás, tudo o que ele fez e a valentia com que combateu contra Amasias, rei de Judá, não está escrito no livro dos Anais dos Reis de Israel?"},
{v:13,t:"Joás adormeceu com seus pais, e Jeroboão sentou-se no seu trono. Joás foi sepultado em Samaria, com os reis de Israel.",n:"A conclusão do reinado vem antes da história da morte de Eliseu, que aconteceu no seu tempo."},
{s:"A morte de Eliseu"},
{v:14,t:"Eliseu caiu doente da doença de que havia de morrer. Joás, rei de Israel, desceu para visitá-lo e chorava diante dele, dizendo: Meu pai, meu pai! Carro de Israel e seu cavaleiro!",np:1,n:"As mesmas palavras que Eliseu gritara quando Elias foi arrebatado (2,12): o rei reconhece que o profeta era a verdadeira força de Israel."},
{v:15,t:"Eliseu lhe disse: Traze um arco e flechas. Ele trouxe um arco e flechas,"},
{v:16,t:"e Eliseu disse ao rei de Israel: Põe a mão no arco. Ele pôs a mão, e Eliseu pôs as suas mãos sobre as mãos do rei,"},
{v:17,t:"e disse: Abre a janela do lado do oriente. Ele a abriu, e Eliseu disse: Atira! E ele atirou. Eliseu disse: Flecha de vitória do Senhor! Flecha de vitória contra a Síria! Tu baterás os arameus em Afec, até exterminá-los.",n:"Uma ação simbólica: o gesto do profeta dá eficácia à palavra. O oriente é a direção de Damasco."},
{v:18,t:"E disse ainda: Toma as flechas. Ele as tomou, e Eliseu disse ao rei de Israel: Bate no chão! Ele bateu três vezes e parou."},
{v:19,t:"O homem de Deus irritou-se contra ele e disse: Devias ter batido cinco ou seis vezes: então terias batido os arameus até exterminá-los; agora só os baterás três vezes.",n:"O rei limita, com a sua fé medrosa, a vitória que Deus lhe queria dar."},
{v:20,t:"Eliseu morreu, e o sepultaram. Naquele ano, bandos de moabitas invadiram o país.",np:1},
{v:21,t:"Uns homens que sepultavam um morto viram um desses bandos, lançaram o cadáver no túmulo de Eliseu e fugiram. Assim que o morto tocou os ossos de Eliseu, reviveu e se pôs de pé.",n:"Mesmo depois de morto, o profeta dá a vida (Eclesiástico 48,13-14). A tradição cristã viu neste episódio uma das raízes da veneração das relíquias dos santos."},
{s:"Vitórias sobre a Síria"},
{v:22,t:"Hazael, rei da Síria, oprimiu Israel durante todo o reinado de Joacaz.",np:1},
{v:23,t:"Mas o Senhor teve compaixão deles e voltou-se para eles, por causa da sua aliança com Abraão, Isaac e Jacó; não quis destruí-los nem rejeitá-los da sua presença, até agora.",n:"Até agora: a frase foi escrita antes da queda de Samaria. A aliança com os patriarcas é mais antiga e mais forte que os pecados dos reis."},
{v:24,t:"Hazael, rei da Síria, morreu, e seu filho Ben-Adad reinou em seu lugar."},
{v:25,t:"Então Joás, filho de Joacaz, retomou das mãos de Ben-Adad, filho de Hazael, as cidades que este tinha tomado pela guerra a Joacaz, seu pai. Três vezes Joás o derrotou, e recuperou as cidades de Israel.",n:"Três vezes, como Eliseu tinha dito (versículo 19)."}
];

window.TEXTOS_SEED["2reis"][14] = [
{s:"Amasias, rei de Judá"},
{v:1,t:"No segundo ano de Joás, filho de Joacaz, rei de Israel, Amasias, filho de Joás, rei de Judá, começou a reinar."},
{v:2,t:"Tinha vinte e cinco anos quando começou a reinar, e reinou vinte e nove anos em Jerusalém. Sua mãe chamava-se Joadan, de Jerusalém."},
{v:3,t:"Fez o que é reto aos olhos do Senhor, mas não como Davi, seu pai. Fez em tudo como tinha feito Joás, seu pai,"},
{v:4,t:"a não ser que os lugares altos não foram suprimidos: o povo continuava a oferecer sacrifícios e a queimar incenso nos lugares altos."},
{v:5,t:"Quando o reino se firmou nas suas mãos, matou os servos que tinham assassinado o rei, seu pai;"},
{v:6,t:"mas não matou os filhos dos assassinos, segundo o que está escrito no livro da Lei de Moisés, onde o Senhor ordenou: Os pais não serão mortos pelos filhos, nem os filhos pelos pais; cada um morrerá pelo seu próprio pecado.",n:"Citação de Deuteronômio 24,16: um dos primeiros sinais, na história, da aplicação da lei do Deuteronômio e da responsabilidade pessoal, que Ezequiel desenvolverá (Ezequiel 18)."},
{v:7,t:"Ele derrotou dez mil edomitas no vale do Sal, tomou Sela na guerra e deu-lhe o nome de Jecteel, que conserva até hoje.",n:"Sela, a Rocha: talvez a futura Petra, capital dos nabateus, ou outra fortaleza de Edom."},
{v:8,t:"Então Amasias enviou mensageiros a Joás, filho de Joacaz, filho de Jeú, rei de Israel, para lhe dizer: Vem, enfrentemo-nos!",np:1},
{v:9,t:"Joás, rei de Israel, mandou responder a Amasias, rei de Judá: O cardo do Líbano mandou dizer ao cedro do Líbano: Dá a tua filha por mulher ao meu filho. Mas os animais selvagens do Líbano passaram e pisaram o cardo.",n:"Uma fábula, como a de Joatão (Juízes 9,8-15): Amasias, o cardo, pretende tratar de igual para igual com o cedro, Israel, muito mais poderoso."},
{v:10,t:"Derrotaste Edom, e o teu coração se ensoberbeceu. Contenta-te com essa glória e fica em casa. Por que provocar uma desgraça, para caíres, tu e Judá contigo?"},
{v:11,t:"Mas Amasias não o ouviu. Joás, rei de Israel, subiu, e ele e Amasias, rei de Judá, enfrentaram-se em Bet-Sames, que pertence a Judá."},
{v:12,t:"Judá foi derrotado por Israel, e cada um fugiu para a sua tenda."},
{v:13,t:"Joás, rei de Israel, prendeu em Bet-Sames Amasias, rei de Judá, filho de Joás, filho de Ocozias, e o levou a Jerusalém. Abriu na muralha de Jerusalém uma brecha de quatrocentos côvados, desde a porta de Efraim até a porta do Ângulo."},
{v:14,t:"Tomou todo o ouro e toda a prata, e todos os objetos que se encontravam na casa do Senhor e nos tesouros do palácio real, e também reféns; e voltou para Samaria."},
{v:15,t:"O resto dos feitos de Joás, o que ele fez, a sua valentia e como combateu contra Amasias, rei de Judá, não está escrito no livro dos Anais dos Reis de Israel?",np:1,n:"Esta conclusão repete a de 13,12-13, porque a guerra com Amasias acabava de ser contada."},
{v:16,t:"Joás adormeceu com seus pais e foi sepultado em Samaria, com os reis de Israel; e seu filho Jeroboão reinou em seu lugar."},
{v:17,t:"Amasias, filho de Joás, rei de Judá, viveu ainda quinze anos depois da morte de Joás, filho de Joacaz, rei de Israel.",np:1},
{v:18,t:"O resto dos feitos de Amasias não está escrito no livro dos Anais dos Reis de Judá?"},
{v:19,t:"Tramaram contra ele uma conspiração em Jerusalém, e ele fugiu para Laquis; mas mandaram atrás dele até Laquis, e ali o mataram."},
{v:20,t:"Trouxeram-no sobre cavalos, e ele foi sepultado em Jerusalém, com seus pais, na Cidade de Davi."},
{v:21,t:"Então todo o povo de Judá tomou Azarias, que tinha dezesseis anos, e o proclamou rei em lugar de Amasias, seu pai.",n:"Azarias é também chamado Ozias (15,30; Isaías 6,1)."},
{v:22,t:"Foi ele que reconstruiu Elat e a devolveu a Judá, depois que o rei adormeceu com seus pais."},
{s:"Jeroboão II, rei de Israel"},
{v:23,t:"No décimo quinto ano de Amasias, filho de Joás, rei de Judá, Jeroboão, filho de Joás, rei de Israel, começou a reinar em Samaria, e reinou quarenta e um anos.",np:1,n:"Jeroboão II deu ao reino do Norte o seu último tempo de prosperidade: é o tempo em que pregaram os profetas Amós e Oseias, denunciando a injustiça escondida sob a riqueza."},
{v:24,t:"Fez o que é mau aos olhos do Senhor; não se afastou de nenhum dos pecados de Jeroboão, filho de Nabat, que fizera Israel pecar."},
{v:25,t:"Foi ele que restabeleceu as fronteiras de Israel, desde a entrada de Emat até o mar da Arabá, segundo a palavra do Senhor, Deus de Israel, que ele tinha dito por meio do seu servo, o profeta Jonas, filho de Amati, de Gat-Hefer.",n:"O mar da Arabá é o mar Morto. Jonas, filho de Amati, é o mesmo profeta a quem se atribui o livro de Jonas."},
{v:26,t:"Porque o Senhor viu a aflição muito amarga de Israel: não restava ninguém, nem jovem nem adulto, e não havia quem socorresse Israel."},
{v:27,t:"O Senhor não tinha dito que apagaria o nome de Israel de debaixo do céu; e os salvou por meio de Jeroboão, filho de Joás.",n:"Mesmo um rei infiel pode ser instrumento da misericórdia de Deus para com o seu povo."},
{v:28,t:"O resto dos feitos de Jeroboão, tudo o que fez, a valentia com que combateu, e como reconquistou para Israel Damasco e Emat, que tinham pertencido a Judá, não está escrito no livro dos Anais dos Reis de Israel?"},
{v:29,t:"Jeroboão adormeceu com seus pais, os reis de Israel, e seu filho Zacarias reinou em seu lugar."}
];

window.TEXTOS_SEED["2reis"][15] = [
{s:"Azarias, rei de Judá"},
{v:1,t:"No vigésimo sétimo ano de Jeroboão, rei de Israel, Azarias, filho de Amasias, rei de Judá, começou a reinar."},
{v:2,t:"Tinha dezesseis anos quando começou a reinar, e reinou cinquenta e dois anos em Jerusalém. Sua mãe chamava-se Jequelia, de Jerusalém."},
{v:3,t:"Fez o que é reto aos olhos do Senhor, em tudo como tinha feito Amasias, seu pai."},
{v:4,t:"Mas os lugares altos não foram suprimidos: o povo continuava a oferecer sacrifícios e a queimar incenso nos lugares altos."},
{v:5,t:"O Senhor feriu o rei, e ele ficou leproso até o dia da sua morte, e morou numa casa à parte; Joatão, filho do rei, governava o palácio e julgava o povo da terra.",n:"As Crônicas explicam a lepra como castigo por ter querido oferecer incenso no templo, função reservada aos sacerdotes (2 Crônicas 26,16-21)."},
{v:6,t:"O resto dos feitos de Azarias, tudo o que ele fez, não está escrito no livro dos Anais dos Reis de Judá?"},
{v:7,t:"Azarias adormeceu com seus pais, e o sepultaram com seus antepassados na Cidade de Davi; e seu filho Joatão reinou em seu lugar."},
{s:"Os últimos reis de Israel"},
{v:8,t:"No trigésimo oitavo ano de Azarias, rei de Judá, Zacarias, filho de Jeroboão, reinou sobre Israel, em Samaria, durante seis meses.",np:1,n:"Começa a decadência final do reino do Norte: em vinte anos, seis reis, quatro deles assassinados. Oseias dirá: fizeram reis sem mim (Oseias 8,4)."},
{v:9,t:"Fez o que é mau aos olhos do Senhor, como tinham feito os seus pais; não se afastou dos pecados de Jeroboão, filho de Nabat, que fizera Israel pecar."},
{v:10,t:"Selum, filho de Jabes, conspirou contra ele, feriu-o em Jeblaam e o matou; e reinou em seu lugar."},
{v:11,t:"O resto dos feitos de Zacarias não está escrito no livro dos Anais dos Reis de Israel?"},
{v:12,t:"Assim se cumpriu a palavra que o Senhor tinha dito a Jeú: Os teus filhos se sentarão no trono de Israel até a quarta geração. E assim aconteceu.",n:"Jeú, Joacaz, Joás, Jeroboão II e Zacarias: a promessa de 10,30 se cumpriu."},
{v:13,t:"Selum, filho de Jabes, começou a reinar no trigésimo nono ano de Azarias, rei de Judá, e reinou um mês em Samaria.",np:1},
{v:14,t:"Manaém, filho de Gadi, subiu de Tersa, entrou em Samaria, feriu Selum, filho de Jabes, em Samaria, e o matou; e reinou em seu lugar."},
{v:15,t:"O resto dos feitos de Selum e a conspiração que tramou não estão escritos no livro dos Anais dos Reis de Israel?"},
{v:16,t:"Então Manaém destruiu Tafsa e todos os seus habitantes, e o seu território desde Tersa, porque não lhe tinham aberto as portas; e rasgou o ventre de todas as mulheres grávidas.",n:"A crueldade que Eliseu previra dos arameus (8,12) é praticada agora por um rei de Israel contra o seu próprio povo."},
{v:17,t:"No trigésimo nono ano de Azarias, rei de Judá, Manaém, filho de Gadi, começou a reinar sobre Israel, e reinou dez anos em Samaria.",np:1},
{v:18,t:"Fez o que é mau aos olhos do Senhor; não se afastou dos pecados de Jeroboão, filho de Nabat, que fizera Israel pecar. No seu tempo,"},
{v:19,t:"Ful, rei da Assíria, invadiu o país; e Manaém deu a Ful mil talentos de prata, para que o ajudasse a firmar o reino nas suas mãos.",n:"Ful é o nome babilônico de Teglat-Falasar III, o grande rei da Assíria, que começa a submeter os reinos da Síria e de Israel. Os anais assírios mencionam o tributo de Manaém."},
{v:20,t:"Manaém impôs esse dinheiro a Israel, a todos os homens ricos, cinquenta siclos de prata por cabeça, para dá-lo ao rei da Assíria. E o rei da Assíria voltou e não ficou no país."},
{v:21,t:"O resto dos feitos de Manaém, tudo o que ele fez, não está escrito no livro dos Anais dos Reis de Israel?"},
{v:22,t:"Manaém adormeceu com seus pais, e seu filho Faceias reinou em seu lugar."},
{v:23,t:"No quinquagésimo ano de Azarias, rei de Judá, Faceias, filho de Manaém, começou a reinar sobre Israel, em Samaria, e reinou dois anos.",np:1},
{v:24,t:"Fez o que é mau aos olhos do Senhor; não se afastou dos pecados de Jeroboão, filho de Nabat, que fizera Israel pecar."},
{v:25,t:"Faceia, filho de Romelias, seu oficial, conspirou contra ele e o feriu em Samaria, na torre do palácio real; tinha consigo cinquenta homens de Galaad. Matou-o e reinou em seu lugar."},
{v:26,t:"O resto dos feitos de Faceias, tudo o que ele fez, não está escrito no livro dos Anais dos Reis de Israel?"},
{v:27,t:"No quinquagésimo segundo ano de Azarias, rei de Judá, Faceia, filho de Romelias, começou a reinar sobre Israel, em Samaria, e reinou vinte anos.",np:1},
{v:28,t:"Fez o que é mau aos olhos do Senhor; não se afastou dos pecados de Jeroboão, filho de Nabat, que fizera Israel pecar."},
{v:29,t:"No tempo de Faceia, rei de Israel, veio Teglat-Falasar, rei da Assíria, e tomou Aion, Abel-Bet-Maaca, Janoe, Cedes, Hasor, Galaad e a Galileia, toda a terra de Neftali; e deportou os seus habitantes para a Assíria.",n:"Em 733 antes de Cristo, a primeira deportação: a Galileia e a Transjordânia tornam-se províncias assírias. Isaías anunciará que sobre essa terra humilhada, a Galileia das nações, brilhará uma grande luz (Isaías 8,23-9,1; Mateus 4,15-16)."},
{v:30,t:"Oseias, filho de Ela, tramou uma conspiração contra Faceia, filho de Romelias; feriu-o, matou-o e reinou em seu lugar, no vigésimo ano de Joatão, filho de Ozias."},
{v:31,t:"O resto dos feitos de Faceia, tudo o que ele fez, não está escrito no livro dos Anais dos Reis de Israel?"},
{s:"Joatão, rei de Judá"},
{v:32,t:"No segundo ano de Faceia, filho de Romelias, rei de Israel, Joatão, filho de Ozias, rei de Judá, começou a reinar.",np:1},
{v:33,t:"Tinha vinte e cinco anos quando começou a reinar, e reinou dezesseis anos em Jerusalém. Sua mãe chamava-se Jerusa, filha de Sadoc."},
{v:34,t:"Fez o que é reto aos olhos do Senhor: agiu em tudo como tinha feito Ozias, seu pai."},
{v:35,t:"Mas os lugares altos não foram suprimidos: o povo continuava a oferecer sacrifícios e a queimar incenso nos lugares altos. Foi ele que construiu a porta superior da casa do Senhor."},
{v:36,t:"O resto dos feitos de Joatão, tudo o que ele fez, não está escrito no livro dos Anais dos Reis de Judá?"},
{v:37,t:"Naqueles dias, o Senhor começou a lançar contra Judá Rasin, rei da Síria, e Faceia, filho de Romelias.",n:"Damasco e Samaria querem arrastar Judá para uma coalizão contra a Assíria: é a guerra siro-efraimita, contexto da profecia do Emanuel (Isaías 7)."},
{v:38,t:"Joatão adormeceu com seus pais e foi sepultado com eles na Cidade de Davi, seu pai; e seu filho Acaz reinou em seu lugar."}
];

window.TEXTOS_SEED["2reis"][16] = [
{s:"Acaz, rei de Judá"},
{v:1,t:"No décimo sétimo ano de Faceia, filho de Romelias, Acaz, filho de Joatão, rei de Judá, começou a reinar."},
{v:2,t:"Acaz tinha vinte anos quando começou a reinar, e reinou dezesseis anos em Jerusalém. Não fez o que é reto aos olhos do Senhor seu Deus, como Davi, seu pai,"},
{v:3,t:"mas andou no caminho dos reis de Israel; chegou a fazer passar pelo fogo o seu filho, segundo as abominações das nações que o Senhor tinha expulsado diante dos filhos de Israel.",n:"Fazer passar pelo fogo: o sacrifício de crianças, praticado nos cultos cananeus e fenícios, e severamente proibido pela Lei (Levítico 18,21; Deuteronômio 18,10)."},
{v:4,t:"Oferecia sacrifícios e queimava incenso nos lugares altos, sobre as colinas e debaixo de toda árvore frondosa."},
{v:5,t:"Então Rasin, rei da Síria, e Faceia, filho de Romelias, rei de Israel, subiram contra Jerusalém para atacá-la; sitiaram Acaz, mas não conseguiram vencê-lo.",np:1,n:"É nesta situação que Isaías vai ao encontro de Acaz e lhe pede que confie no Senhor, anunciando o sinal do Emanuel (Isaías 7,1-16)."},
{v:6,t:"Naquele tempo, Rasin, rei da Síria, devolveu Elat a Edom e expulsou os judeus de Elat; e os edomitas vieram a Elat e ali habitam até hoje."},
{v:7,t:"Acaz enviou mensageiros a Teglat-Falasar, rei da Assíria, para lhe dizer: Sou teu servo e teu filho. Sobe e livra-me da mão do rei da Síria e da mão do rei de Israel, que se levantaram contra mim.",n:"Em vez de confiar no Senhor, como Isaías lhe pedia, Acaz se faz vassalo da Assíria: Judá perde a sua independência."},
{v:8,t:"E Acaz tomou a prata e o ouro que se encontravam na casa do Senhor e nos tesouros do palácio real, e os enviou como presente ao rei da Assíria."},
{v:9,t:"O rei da Assíria atendeu-o: subiu contra Damasco, tomou-a, deportou os seus habitantes para Cir e matou Rasin.",n:"Em 732 antes de Cristo, Damasco cai; o reino arameu desaparece."},
{v:10,t:"O rei Acaz foi a Damasco ao encontro de Teglat-Falasar, rei da Assíria. Vendo o altar que havia em Damasco, o rei Acaz enviou ao sacerdote Urias o modelo do altar e o seu desenho, com todos os detalhes da sua construção.",np:1},
{v:11,t:"O sacerdote Urias construiu o altar, segundo tudo o que o rei Acaz lhe mandara de Damasco; assim o fez o sacerdote Urias antes da volta do rei Acaz de Damasco."},
{v:12,t:"Quando o rei voltou de Damasco, viu o altar, aproximou-se dele e subiu"},
{v:13,t:"e queimou nele o seu holocausto e a sua oblação, derramou a sua libação e aspergiu sobre o altar o sangue dos seus sacrifícios de comunhão."},
{v:14,t:"Quanto ao altar de bronze que estava diante do Senhor, ele o tirou da frente do templo, do lugar entre o novo altar e a casa do Senhor, e o pôs ao lado do novo altar, ao norte."},
{v:15,t:"E o rei Acaz deu esta ordem ao sacerdote Urias: Sobre o altar grande oferecerás o holocausto da manhã e a oblação da tarde, o holocausto do rei e a sua oblação, o holocausto de todo o povo da terra, as suas oblações e as suas libações; e sobre ele derramarás todo o sangue dos holocaustos e todo o sangue dos sacrifícios. Quanto ao altar de bronze, eu verei o que fazer com ele.",n:"O altar de Salomão é posto de lado para dar lugar a uma cópia do altar de Damasco: a submissão política traz consigo a imitação religiosa."},
{v:16,t:"O sacerdote Urias fez tudo o que o rei Acaz lhe tinha ordenado."},
{v:17,t:"O rei Acaz cortou os painéis das bases e tirou delas as bacias; tirou também o mar de cima dos bois de bronze que o sustentavam, e o pôs sobre um pavimento de pedra.",n:"O bronze foi talvez usado para pagar o tributo à Assíria."},
{v:18,t:"Por causa do rei da Assíria, modificou também no templo do Senhor o pórtico coberto do sábado, que tinha sido construído no templo, e a entrada exterior do rei."},
{v:19,t:"O resto dos feitos de Acaz, o que ele fez, não está escrito no livro dos Anais dos Reis de Judá?"},
{v:20,t:"Acaz adormeceu com seus pais e foi sepultado com eles na Cidade de Davi; e seu filho Ezequias reinou em seu lugar."}
];
